INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', '_meta.language', 'de', 'de');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', '_meta.reviewed', 'de', 'true');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'backLink', 'de', '← Zurück zur Übersicht');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'header.eyebrow', 'de', 'Wissen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'header.title', 'de', 'Staatlich zertifizierte Anbieter');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'header.sub', 'de', 'Wo Sie die offizielle, von der Regierung veröffentlichte Liste akkreditierter Dienstleister oder Peppol-fähiger Software für jedes Land finden — direkt anhand der eigenen Website der jeweiligen Behörde verifiziert, nicht anhand einer Zusammenfassung Dritter.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'header.lastUpdated', 'de', 'Zuletzt aktualisiert:');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'statusBanner.text', 'de', 'Dies ist ein <strong>erster Satz verifizierter Links</strong>, keine vollständige Übersicht aller 28 erfassten Rechtsordnungen. Jeder Link unten wurde direkt anhand der eigenen Website der genannten Regierung/Behörde geprüft. Mehrere Länder in diesem Tracker führen überhaupt kein öffentliches Akkreditierungsregister — siehe den Hinweis in Abschnitt 3, bevor Sie annehmen, dass eines existiert.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'stats.label1', 'de', 'Bisher verifizierte Länder');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'stats.label2', 'de', 'Verschiedene verwendete Akkreditierungsbegriffe');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'stats.label3', 'de', 'Globales Peppol-Anbieterverzeichnis');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec1.heading', 'de', 'Gleiche Idee, unterschiedliche Namen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec1.intro', 'de', 'Jedes Land unten betreibt eine Version desselben Konzepts — eine staatlich anerkannte Liste von Software oder Vermittlern, auf die Sie sich sicher verlassen können —, aber jedes verwendet dafür seinen eigenen Begriff.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec1.card1.body', 'de', 'Verwendet in den VAE. Der Vermittler, der Ihre E-Rechnungen über das Peppol-Netzwerk in Ihrem Namen validiert und überträgt.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec1.card2.body', 'de', 'Verwendet in Mexiko. Der von der SAT autorisierte Dritte, der Ihre CFDI stempelt (timbrar) und ihr Rechtsgültigkeit verleiht.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec1.card3.body', 'de', 'Verwendet in Peru. Ein OSE validiert Ihre Rechnung mit derselben Rechtsautorität wie die SUNAT selbst; ein PSE signiert in Ihrem Namen mit seinem eigenen Zertifikat.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec1.card4.body', 'de', 'Verwendet in Indien. Ein lizenzierter Vermittler, der die Software-/API-Ebene bereitstellt, die einen Steuerpflichtigen mit der GSTN verbindet.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec1.card5.title', 'de', 'Peppol Service Provider / Access Point');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec1.card5.body', 'de', 'Verwendet in Malaysia, Singapur, Australien und jedem anderen Peppol-basierten Markt. Ein akkreditierter Access Point verbindet Ihr Unternehmen mit dem gemeinsamen Peppol-Netzwerk.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.heading', 'de', 'Verifizierte offizielle Links, nach Land');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.intro', 'de', 'Klicken Sie durch zur eigenen Seite der Behörde — prüfen Sie den aktuellen Status eines bestimmten Anbieters immer dort direkt, bevor Sie etwas unterschreiben, da sich diese Listen ändern.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.h1', 'de', 'Land');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.h2', 'de', 'Was gelistet ist');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.h3', 'de', 'Offizielle Quelle');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.uae', 'de', 'Register des Finanzministeriums für vorab genehmigte / akkreditierte E-Invoicing-Dienstleister (ASPs)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.mexico', 'de', 'Register der SAT für Proveedores Autorizados de Certificación');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.peru', 'de', 'Offizieller padrón (Register) der SUNAT für autorisierte OSE- und PSE-Anbieter');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.india', 'de', 'Liste der GSTN mit lizenzierten GST Suvidha Providern');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.malaysia', 'de', 'Register der MDEC (Peppol-Behörde Malaysias) für akkreditierte Peppol Service Provider');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.singapore', 'de', 'Liste der IMDA mit autorisierten Access-Point-Anbietern und InvoiceNow-Ready-Lösungen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.australia', 'de', 'Register der ATO (australische Peppol-Behörde) für akkreditierte Peppol-Dienstleister');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.france', 'de', 'Liste der DGFiP mit registrierten Plateformes Agréées (früher PDP)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.franceNote', 'de', 'Frankreichs genaue Liste befindet sich innerhalb der breiteren Website impots.gouv.fr der DGFiP statt unter einer festen, stabilen URL, die wir mit voller Sicherheit verifizieren könnten — suchen Sie direkt auf dieser Website nach "liste des plateformes agréées" für die aktuelle Version.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec3.heading', 'de', 'Wo dieses Muster nicht gilt');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec3.intro', 'de', 'Mehrere bedeutende Märkte in diesem Tracker führen schlicht kein öffentliches Anbieterakkreditierungsregister — gut zu wissen, damit Sie nicht nach etwas suchen, das nicht existiert.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec3.card1.body', 'de', 'KSeF und SDI sind beide direkte Regierungsplattformen — jede konforme Software kann sich über das veröffentlichte API/Schema verbinden, ohne eine formelle Ebene eines "akkreditierten Vermittlers", gegen die zertifiziert werden müsste.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec3.card2.body', 'de', 'Steuerpflichtige zertifizieren sich selbst als autorisierte Aussteller direkt bei der Steuerbehörde (SEFAZ, SII); in keinem der beiden Länder gibt es ein vergleichbares PAC-/OSE-artiges Drittanbieter-Akkreditierungsmodell.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec3.card3.body', 'de', 'Die ZATCA veröffentlicht keine vergleichbare öffentliche Liste — Compliance bedeutet, dass Ihr Rechnungssystem direkt die veröffentlichte technische Spezifikation erfüllt, nicht eine Vermittlerakkreditierung.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec4.heading', 'de', 'Eine Ressource, die jeden Peppol-Markt abdeckt');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec4.body', 'de', 'Für jedes Peppol-basierte Land, das noch nicht in der obigen Tabelle steht — Belgien, Norwegen, Dänemark und andere — führt OpenPeppol selbst (das leitende Gremium des Netzwerks) ein einziges globales Register aller zertifizierten Peppol-Dienstleister, durchsuchbar nach Land des rechtlichen Sitzes.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.heading', 'de', 'Wie es weitergeht');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.card1.title', 'de', '🏷️ Verstehen Sie zuerst die Anbieterkategorien');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.card1.body', 'de', '"Anbietertypen" (unter Wissen) schlüsselt die Kategorien ERP, Lösungsanbieter, Steuer-Compliance, Technologie und Beratung auf, bevor Sie mit dem Durchsuchen staatlicher Listen beginnen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.card2.title', 'de', '🗓️ Bereit für eine Anbieterauswahl?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.card2.body', 'de', '"Vorbereitung auf eine Vorgabe" (unter Wissen) erklärt, wie Sie einen Anbieter bewerten und auswählen, sobald Sie die richtige Liste gefunden haben.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.card3.title', 'de', '🌍 Prüfen Sie die spezifischen Anforderungen Ihres Landes');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.card3.body', 'de', 'Das Menü der Länderanalysen behandelt die genauen Registrierungsschritte, technischen Spezifikationen und Sanktionen für jede der 28 hier erfassten Rechtsordnungen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.card4.title', 'de', '📬 Diese Liste wird wachsen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.card4.body', 'de', 'Weitere Länder werden hier hinzugefügt, sobald wir ihre offiziellen Quellen direkt verifizieren — Abonnenten werden benachrichtigt, wenn neue Einträge veröffentlicht werden.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'footer.text', 'de', 'Diese Seite verlinkt direkt zu offiziellen Regierungs- und Behördenquellen, verifiziert zum oben genannten Datum, und dient der allgemeinen Information — sie stellt keine Empfehlung eines bestimmten Anbieters dar, und die Aufnahme in eine Regierungsliste ist keine Garantie für die Eignung für Ihre spezifischen Bedürfnisse. Bestätigen Sie den aktuellen Akkreditierungsstatus eines Anbieters immer direkt auf der verlinkten offiziellen Seite, bevor Sie eine Vereinbarung unterzeichnen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', '_meta.language', 'de', 'de');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', '_meta.reviewed', 'de', 'true');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'backLink', 'de', '← Zurück zur Übersicht');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'header.eyebrow', 'de', 'Wissen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'header.title', 'de', 'Auswirkungen der Vorgabe');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'header.sub', 'de', 'Eine neue E-Invoicing-Vorgabe bleibt selten allein bei der IT. Diese Seite geht durch, wo die Auswirkungen im Unternehmen tatsächlich ankommen — technisch, prozessual, finanziell und organisatorisch —, damit Sie das eigentliche Projekt abschätzen können, nicht nur den Softwarekauf.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'header.lastUpdated', 'de', 'Zuletzt aktualisiert:');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'stats.label1', 'de', 'Typischerweise beteiligte Funktionen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'stats.label2', 'de', 'Manche Ausstellungsfristen, statt Tagen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'stats.label3', 'de', 'Abgelehnte Rechnung kann eine Lieferung blockieren');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.heading', 'de', 'Warum das größer ist als ein IT-Projekt');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.intro', 'de', 'Der häufigste Fehler bei der Abschätzung einer Vorgabenreaktion ist, sie als "unser ERP an ein neues Format anschließen" zu behandeln. In der Praxis betreffen die meisten Vorgaben mindestens fünf Funktionen gleichzeitig — und jede entdeckt ihren Teil der Arbeit zu einem anderen Zeitpunkt, meist zu spät.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.card1.title', 'de', 'Finanzen &amp; Steuern');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.card1.body', 'de', 'Trägt die Compliance-Pflicht selbst und meist die Beziehung zur gewählten Plattform/zum Vermittler — hat aber oft keinen Einblick, ob das ERP das Geforderte tatsächlich liefern kann.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.card2.title', 'de', 'IT');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.card2.body', 'de', 'Baut die Integration, wird aber häufig erst hinzugezogen, nachdem sich Finanzen bereits auf eine Frist festgelegt hat — was wenig Spielraum lässt, Umfang oder Zeitplan zu beeinflussen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.card3.title', 'de', 'Recht &amp; Datenschutz');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.card3.body', 'de', 'Muss sich zu Datenresidenz, grenzüberschreitender Übermittlung und Vertragsbedingungen mit neuen Vermittlern äußern — oft die zuletzt konsultierte Funktion, obwohl sie eine der ersten sein sollte.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.card4.title', 'de', 'Vertrieb, Einkauf &amp; Logistik');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.card4.body', 'de', 'Erfassen die Stammdaten (Steuernummern, Klassifizierungscodes, Adressen), die Clearing-Systeme nun streng validieren — und spüren es operativ, wenn eine Lieferung wegen einer abgelehnten Rechnung feststeckt.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.heading', 'de', 'Technische Auswirkungen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.intro', 'de', 'Hier beginnt üblicherweise die Planung — und hier wird die tatsächliche Komplexität am leichtesten unterschätzt, besonders sobald mehr als eine Rechtsordnung betroffen ist.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card1.title', 'de', 'Integrationsansatz');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card1.body', 'de', 'Direkte ERP-zu-Plattform-API-Integration, eine Middleware-/Dienstleisterebene (PAC, OSE, Access Point), oder ein manuelles Webportal als Notlösung bei geringem Volumen — jede Variante hat ein anderes Kosten-, Geschwindigkeits- und Wartungsprofil.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card1.note', 'de', 'Die "manuelle Portal"-Option wirkt bei geringem Volumen oft kostenlos, wird aber zum Engpass, sobald das Volumen wächst — modellieren Sie beide Szenarien.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card2.title', 'de', 'Format-Fragmentierung');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card2.body', 'de', 'Es gibt kein universelles E-Rechnungsformat. UBL, CII, JSON und länderspezifische Schemata (CFDI, FA(3), e-fapiao) existieren nebeneinander — ein Unternehmen, das in mehreren Vorgabe-Märkten tätig ist, pflegt realistisch mehrere verschiedene technische Integrationen, nicht eine.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card3.title', 'de', 'Stammdatenqualität');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card3.body', 'de', 'Clearing-Systeme validieren Steuernummern, Produkt-/Dienstleistungsklassifizierungscodes und Käuferdaten in Echtzeit. Daten, die für ein internes ERP-Feld "gut genug" waren, scheitern oft beim ersten Kontakt mit einer Regierungsplattform an der Validierung.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card3.note', 'de', 'Dies ist durchweg die mit Abstand größte Quelle früher Ablehnungen — ein gezielter Datenbereinigungsdurchlauf vor dem Go-Live lohnt sich, nicht erst danach.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card4.title', 'de', 'Digitale Zertifikate &amp; Signatur');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card4.body', 'de', 'Viele Regime verlangen ein qualifiziertes digitales Zertifikat zum Signieren von Rechnungen oder zur Authentifizierung von API-Aufrufen. Zertifikate laufen ab, benötigen Erneuerungsprozesse und müssen manchmal an einen Drittanbieter delegiert werden — eine echte laufende Verwaltungsaufgabe, kein einmaliger Einrichtungsschritt.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card5.title', 'de', 'Resilienz &amp; Notfallplanung');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card5.body', 'de', 'Was passiert, wenn die Regierungsplattform ausfällt? Mehrere Regime definieren explizite Offline-/Notfallmodi (Polens Offline24, Saudi-Arabiens Ausfallmodus) — dies von Anfang an einzuplanen erspart Hektik, wenn es tatsächlich passiert.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card6.title', 'de', 'Archivierungspflichten');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card6.body', 'de', 'Aufbewahrungsfristen für E-Rechnungen sind oft länger und formatspezifischer als allgemeine Buchhaltungsvorschriften (10 Jahre sind üblich; manche Kategorien laufen länger). In der Regel muss die ursprüngliche strukturierte Datei aufbewahrt werden — nicht eine gedruckte oder PDF-Darstellung.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.heading', 'de', 'Datenresidenz &amp; -souveränität');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.intro', 'de', 'Leicht zu übersehen, wenn die Rechnungsstellung in einem Shared Service Center zentralisiert ist — eine Vorgabe in einem Land kann Auswirkungen darauf haben, wo und wie diese Daten verarbeitet werden dürfen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.card1.title', 'de', 'Wo liegen die Daten tatsächlich?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.card1.body', 'de', 'Manche Clearing-Modelle leiten Rechnungsinhalte bewusst über staatliche Infrastruktur oder lokal akkreditierte Vermittler — es lohnt sich zu prüfen, ob Ihr gewählter Anbieter Daten innerhalb des betreffenden Landes verarbeitet und speichert, oder anderswo.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.card2.title', 'de', 'Konflikte mit Shared Service Centern');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.card2.body', 'de', 'Eine gängige Architektur — Rechnungsstellung für viele Länder zentral aus einem Hub — kann mit der Erwartung eines bestimmten Landes kollidieren, dass bestimmte Daten lokal bleiben. Es lohnt sich, dies markt für Markt explizit zu prüfen, statt anzunehmen, dass eine globale Plattform überall automatisch passt.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.card3.title', 'de', 'Erhöhte staatliche Sichtbarkeit');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.card3.body', 'de', 'Clearing- und Echtzeit-Meldemodelle geben Steuerbehörden weit granularere, nahezu live Einblicke in Geschäftstransaktionen, als es periodische Meldungen je taten. Manche Unternehmen sehen darin ein echtes wettbewerbssensibles Anliegen, das es wert ist, der Geschäftsleitung mitzuteilen, auch wenn es die Compliance-Pflicht selbst nicht ändert.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.card4.title', 'de', 'Risiko der Anbieterbindung');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.card4.body', 'de', 'Länderspezifische Vermittler (ein bestimmter PAC, OSE oder Access Point) können sich unbemerkt zu tragender Infrastruktur entwickeln. Verstehen Sie Ihren Ausstiegs-/Migrationsweg, bevor Sie von einem abhängig sind — manche Regime schreiben Anbietern genau aus diesem Grund eine Mindest-Fortführungsfrist vor.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.heading', 'de', 'Prozess- und Dokumentenworkflow-Änderungen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.intro', 'de', 'Der Teil, der Finanzteams am härtesten überrascht: vertraute Dokumenten-Workflows — Gutschriften, Lastschriften, Korrekturen — überstehen eine Vorgabe nicht immer unverändert.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.h1', 'de', 'Alter Prozess');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.h2', 'de', 'Was sich unter vielen Vorgaben ändert');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r1k', 'de', 'Eine Gutschrift/Lastschrift frei ausstellen, um einen Fehler zu korrigieren');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r1v', 'de', 'Stattdessen ein formeller "Korrekturrechnungs"-Prozess, oft mit eigenem Dokumenttyp und eigenen Validierungsregeln — manche Regime akzeptieren Ad-hoc-Korrekturnotizen überhaupt nicht mehr (Polens KSeF hat die traditionelle "nota korygująca" zugunsten strukturierter Korrekturen über die Plattform selbst abgeschafft)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r2k', 'de', 'Eine ausgestellte Rechnung direkt bearbeiten oder stornieren');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r2v', 'de', 'Nach Freigabe/Meldung können viele Rechnungen rechtlich nicht mehr bearbeitet werden — der einzige Weg ist eine formelle Gutschrift oder ein neues Korrekturdokument, selbst bei kleineren Fehlern');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r3k', 'de', 'Rechnungen zum Monatsende bündeln');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r3v', 'de', 'Ausstellungsfenster werden nun in Stunden oder Tagen gemessen (24 Stunden in Saudi-Arabien für B2C-Meldungen; 5 Werktage in Rumänien und der Slowakei) und erzwingen eine nahezu Echtzeit-Ausstellung');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r4k', 'de', 'Annehmen, dass eine Rechnung nach Versand gültig ist');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r4v', 'de', 'Eine abgelehnte Rechnung hat in einem Clearing-Modell überhaupt keine Rechtswirkung — in der Praxis kann dies den Warenversand bis zur Klärung aufhalten, ein Lieferkettenproblem, nicht nur ein buchhalterisches');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r5k', 'de', 'Der Käufer akzeptiert eine Rechnung stillschweigend');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r5v', 'de', 'Manche Regime geben Käufern ein aktives Annahme-/Ablehnungsfenster (Malaysia: 72 Stunden) — Schweigen bedeutet nicht automatisch Annahme, und das Verpassen dieses Fensters kann eine vollständige Gutschrift/Lastschrift statt einer einfachen Stornierung erzwingen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.heading', 'de', 'Finanzielle &amp; kommerzielle Auswirkungen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.intro', 'de', 'Über die direkten Kosten der Compliance-Software hinaus gibt es Effekte zweiter Ordnung, die es wert sind, frühzeitig vor die Finanzleitung zu bringen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.card1.title', 'de', 'Kostenstruktur der Compliance');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.card1.body', 'de', 'Transaktionsgebühren von Vermittlern, Softwarelizenzen, Zertifikatskosten und Integrationsaufwand skalieren alle unterschiedlich — ein Kostenmodell, das bei Pilotvolumen gut aussieht, kann bei vollem Produktionsvolumen ganz anders aussehen. Modellieren Sie es im Maßstab, bevor Sie sich auf einen Anbieter festlegen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.card2.title', 'de', 'Cashflow, in beide Richtungen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.card2.body', 'de', 'Manche Regime belohnen konformes E-Invoicing mit schnelleren Zahlungsfristen (5-Tage-Zahlungsziele in Neuseeland und im australischen öffentlichen Sektor). Aber eine abgelehnte oder verzögerte Freigabe kann die Zahlung ebenso leicht aufhalten — derselbe Mechanismus wirkt in beide Richtungen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.card3.title', 'de', 'Das Risiko Ihres Kunden, nicht nur Ihres');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.card3.body', 'de', 'In vielen Regimen kann eine nicht konforme Rechnung von Ihnen den eigenen Vorsteuerabzug oder die Ausgabenerstattung Ihres Kunden blockieren. Das macht aus Ihrer Compliance-Lücke dessen finanzielles Problem — ein echtes Beziehungsrisiko, nicht nur ein internes.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.card4.title', 'de', 'Reibung beim Markteintritt');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.card4.body', 'de', 'Der Eintritt in einen neu regulierten Markt ist nicht mehr nur eine Vertriebsentscheidung — Sie benötigen möglicherweise eine lokale Registrierung, eine Vermittlerbeziehung und eine technische Integration, bevor Sie dort auch nur einem einzigen Kunden rechtmäßig eine Rechnung stellen können.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.heading', 'de', 'Organisatorische Bereitschaft');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.intro', 'de', 'Der am schwersten greifbare Auswirkungsbereich, und oft derjenige, der entscheidet, ob der technische Rollout tatsächlich reibungslos verläuft.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.card1.title', 'de', 'Ein Programm, nicht fünf Projekte');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.card1.body', 'de', 'Wenn Finanzen, IT, Recht und Vertrieb/Einkauf die Vorgabe jeweils unabhängig voneinander, nach ihrem eigenen Zeitplan entdecken, ist das ein Rezept für späte Überraschungen. Ein einzelner funktionsübergreifender Verantwortlicher senkt dieses Risiko deutlich.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.card2.title', 'de', 'Verfolgung des Konzern-/Tochterunternehmens-Umfangs');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.card2.body', 'de', 'Viele Vorgaben werden stufenweise nach Umsatzschwelle eingeführt, manchmal berechnet über den gesamten Konzern statt pro Einheit (wie in den Regeln Neuseelands und Malaysias). Recht und Finanzen benötigen einen gemeinsamen, aktuellen Überblick über die Konzernstruktur, um zu wissen, wer tatsächlich betroffen ist, und wann.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.card3.title', 'de', 'Schulung der Basisebene');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.card3.body', 'de', 'Mitarbeiter in der Auftragserfassung und in Kreditoren-/Debitorenbuchhaltung erfassen meist die strengeren Stammdaten, die diese Systeme verlangen — sie zu schulen, warum eine Steuernummer oder ein Klassifizierungscode jetzt wichtiger ist als früher, zahlt sich schnell aus.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.card4.title', 'de', 'Laufende Datenverwaltung');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.card4.body', 'de', 'Eine einmalige Datenbereinigung vor Go-Live verschlechtert sich mit der Zeit, wenn neue Kunden und Lieferanten hinzukommen. Ein dauerhafter Prozess zur Validierung der Handelspartner-Stammdaten hält die Ablehnungsraten dauerhaft niedrig, nicht nur am ersten Tag.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.heading', 'de', 'Fragen, die sich am ersten Tag lohnen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.intro', 'de', 'Eine schnelle erste Checkliste für den Moment, in dem eine neue Vorgabe auf Ihrem Radar auftaucht — bevor Sie sich in technische Spezifikationen vertiefen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.q1', 'de', 'Welche unserer Rechtseinheiten sind tatsächlich betroffen, und ab wann — geprüft anhand der Konzern-Umsatzschwellen, sofern relevant, nicht nur anhand der Zahlen unserer eigenen Einheit?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.q2', 'de', 'Welches Compliance-Modell nutzt dieses Land — Post-Audit, Meldung, Freigabe, zentralisierte Plattform oder Peppol-basiert — und was bedeutet das für unseren Integrationsansatz?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.q3', 'de', 'Kann unser aktuelles ERP das erforderliche Format nativ erzeugen, oder benötigen wir eine Dienstleister-/Middleware-Ebene?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.q4', 'de', 'Wo findet die Rechnungsstellung für diesen Markt derzeit statt — ein Shared Service Center, ein lokales Team — und wirft dieser Standort Fragen zur Datenresidenz auf?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.q5', 'de', 'Wie ist die aktuelle Qualität unserer Stammdaten für Kunden/Lieferanten in diesem Markt — hat das schon jemand tatsächlich geprüft?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.q6', 'de', 'Was passiert operativ, wenn eine Rechnung abgelehnt wird — wer wird benachrichtigt, und wie schnell kann es gelöst werden, bevor es eine Lieferung oder Zahlung beeinträchtigt?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.q7', 'de', 'Wer ist hierfür funktionsübergreifend verantwortlich — gibt es eine verantwortliche Person, oder ist dies im Stillen das Problem von fünf verschiedenen Personen?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.q8', 'de', 'Wie hoch sind die realistischen Kosten bei vollem Produktionsvolumen, nicht bei Pilotvolumen?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.heading', 'de', 'Wie es weitergeht');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.card1.title', 'de', '📘 Verstehen Sie zuerst die Arten von Vorgaben');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.card1.body', 'de', 'Falls noch nicht geschehen: "Arten von Vorgaben" (ebenfalls unter Wissen) erklärt die auf dieser Seite genannten Compliance-Modelle ausführlicher.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.card2.title', 'de', '🗓️ Bereit, mit der Planung zu beginnen?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.card2.body', 'de', '"Vorbereitung auf eine Vorgabe" (unter Wissen) behandelt, wen Sie einbeziehen sollten, wann Sie beginnen sollten und wie Sie die Anbieterauswahl angehen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.card3.title', 'de', '🌍 Prüfen Sie die Anforderungen Ihres spezifischen Landes');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.card3.body', 'de', 'Das Menü der Länderanalysen behandelt die genaue technische Spezifikation, Registrierungsschritte und Sanktionen für jede der 28 hier erfassten Rechtsordnungen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.card4.title', 'de', '✅ Finden Sie einen akkreditierten Anbieter');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.card4.body', 'de', '"Staatlich zertifizierte Anbieter" (unter Wissen) verlinkt direkt zu den offiziellen Regierungsregistern für akkreditierte Dienstleister, Land für Land.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'footer.text', 'de', 'Diese Seite bietet allgemeinen Bildungskontext zur Unterstützung der internen Planung und stellt keine Rechts-, Steuer- oder technische Umsetzungsberatung dar. Konkrete Anforderungen variieren je nach Land sowie Ihren eigenen Systemen und Ihrer Konzernstruktur — konsultieren Sie die jeweilige Länderanalyse und einen qualifizierten Berater, bevor Sie Umsetzungsentscheidungen treffen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', '_meta.language', 'de', 'de');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', '_meta.reviewed', 'de', 'true');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'backLink', 'de', '← Zurück zur Übersicht');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'header.eyebrow', 'de', 'Wissen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'header.title', 'de', 'Arten von Vorgaben');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'header.sub', 'de', 'Die E-Invoicing-Regeln jedes Landes lassen sich auf eine Handvoll zugrunde liegender Modelle zurückführen. Sobald Sie erkennen, welches Modell ein Land verwendet, wirken seine spezifischen Regeln nicht mehr willkürlich.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'header.lastUpdated', 'de', 'Zuletzt aktualisiert:');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'stats.label1', 'de', 'Weltweit genutzte Kernmodelle');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'stats.label2', 'de', 'CTC-Varianten');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'stats.label3', 'de', 'In diesem Tracker erfasste Länder');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.heading', 'de', 'Die eine Frage, die alles erklärt');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.intro', 'de', 'Bevor Sie Formate und Fristen vergleichen, hilft es, sich zu jedem Länderregime eine einzige Frage zu stellen: <strong style="color:var(--text-lo);">Sieht die Steuerbehörde die Rechnung, und wenn ja, bevor oder nachdem sie den Käufer erreicht?</strong>');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card1.title', 'de', 'Nie (oder nur auf Anfrage)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card1.body', 'de', 'Die Steuerbehörde sieht einzelne Rechnungen nicht routinemäßig — sie prüft Aufzeichnungen später, im Rahmen einer Prüfung. Dies ist das am wenigsten eingreifende Modell.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card1.note', 'de', 'Beispiele: Vereinigtes Königreich, Kanada, Vereinigte Staaten (freiwillig).');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card2.title', 'de', 'Danach, nahezu in Echtzeit');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card2.body', 'de', 'Die Rechnung erreicht den Käufer direkt, aber eine Kopie oder Zusammenfassung der Transaktionsdaten wird der Steuerbehörde kurz danach gemeldet — oft innerhalb von Tagen, manchmal sofort.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card2.note', 'de', 'Beispiele: Frankreichs E-Reporting-Schicht, Spaniens SII, Ungarns RTIR.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card3.title', 'de', 'Vor der Zustellung — Freigabe');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card3.body', 'de', 'Die Rechnung muss von der Steuerbehörde oder einem in ihrem Auftrag handelnden akkreditierten Vermittler validiert (und oft digital gestempelt) werden, bevor sie den Käufer überhaupt rechtmäßig erreichen darf.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card3.note', 'de', 'Beispiele: Italiens SDI, Polens KSeF, Mexikos CFDI, Saudi-Arabiens ZATCA.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.heading', 'de', 'Die sieben Modelle in der Praxis');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.intro', 'de', 'In der Praxis verbinden sich diese Fragen zu sieben erkennbaren Architekturen — die meisten Länder in diesem Tracker passen eindeutig zu einer davon.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card1.title', 'de', '1. Post-Audit');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card1.body', 'de', 'Unternehmen tauschen Rechnungen frei aus, in welchem Format sie auch vereinbaren. Die Steuerbehörde prüft Aufzeichnungen im Nachhinein, im Rahmen einer Prüfung, statt Transaktionen bei ihrem Auftreten zu kontrollieren.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card2.title', 'de', '2. Echtzeit-Meldung (CTC)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card2.body', 'de', 'Rechnungen werden direkt zwischen Unternehmen ausgetauscht, aber Transaktionsdaten — manchmal die vollständige Rechnung, manchmal eine Zusammenfassung — werden zusätzlich nahezu in Echtzeit an die Steuerbehörde gemeldet, parallel zur Zustellung, nicht anstelle davon.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card3.title', 'de', '3. Freigabe (CTC)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card3.body', 'de', 'Das strengste Modell: Eine Rechnung hat keine Rechtswirkung, bis die Steuerbehörde (oder ihr Beauftragter) sie validiert und eine Freigabereferenz zurückgegeben hat. Erst dann kann sie an den Käufer geliefert werden.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card4.title', 'de', '4. Zentralisierte Plattform');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card4.body', 'de', 'Ein einziges staatlich betriebenes System übernimmt sowohl Validierung als auch Zustellung — Käufer und Verkäufer interagieren beide mit derselben zentralen Plattform, statt über einen Anbieter ihrer Wahl zu gehen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card5.title', 'de', '5. Dezentraler Austausch — Netzwerk vorgeschrieben (Peppol)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card5.body', 'de', 'Keine staatliche Plattform, aber ein bestimmtes Netzwerk <em>ist</em> gesetzlich vorgeschrieben. Unternehmen verbinden sich einmal mit einem akkreditierten Access Point, und Rechnungen werden Peer-to-Peer in einem gemeinsamen Format geleitet — das "4-Corner"-Modell — weil die Vorgabe selbst Peppol als erforderlichen Kanal benennt.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card6.title', 'de', '6. Reine Formatvorgabe — kein vorgeschriebener Kanal');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card6.body', 'de', 'Ein wirklich leichteres Muster, das sich leicht mit Modell 5 verwechseln lässt, sich aber deutlich unterscheidet: Das Gesetz schreibt ein strukturiertes Format vor, legt aber nicht fest, <em>wie</em> die Rechnung zugestellt werden muss — E-Mail, jedes Netzwerk, jede bilaterale Vereinbarung ist zulässig, solange der Inhalt korrekt strukturiert ist. Keine Freigabe, keine vorgeschriebene Meldeebene, kein erforderliches Netzwerk.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card6.note', 'de', 'Dänemark ist eine noch leichtere Variante — sein Gesetz schreibt die <em>Fähigkeit</em> vor, strukturierte Rechnungen zu senden/empfangen, nicht dass jede Rechnung tatsächlich so ausgetauscht wird.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card7.title', 'de', '7. Dezentraler Austausch + Meldung (5-Corner)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card7.body', 'de', 'Peppols 4-Corner-Netzwerk mit einem fünften Teilnehmer: der Steuerbehörde, die Transaktionsdaten automatisch als Nebenprodukt des normalen Austauschs erhält, statt einer separaten Meldung.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.heading', 'de', '"CTC" ist eine Familie, keine einzelne Sache');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.intro', 'de', 'Continuous Transaction Controls (CTC) ist ein Oberbegriff, der die Modelle 2 und 3 oben umfasst — beide geben der Steuerbehörde nahezu Echtzeit-Einblick, unterscheiden sich aber in einem in der Praxis enorm wichtigen Punkt: Sieht die Regierung die Rechnung, bevor oder nachdem sie rechtsgültig wird?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.h1', 'de', 'Frage');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.h2', 'de', 'CTC — Meldung');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.h3', 'de', 'CTC — Freigabe');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r1k', 'de', 'Wer sieht die Rechnung zuerst?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r1v1', 'de', 'Der Käufer — die Meldung erfolgt parallel oder kurz danach');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r1v2', 'de', 'Die Steuerbehörde — nichts wird zugestellt, bis es freigegeben ist');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r2k', 'de', 'Rechtsgültigkeit');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r2v1', 'de', 'Die Rechnung ist ab Ausstellung gültig; die Meldung ist eine parallele Pflicht');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r2v2', 'de', 'Die Rechnung hat keine Rechtswirkung, bis sie freigegeben ist');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r3k', 'de', 'Fehlerfall');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r3v1', 'de', 'Eine verspätete oder fehlende Meldung ist ein Compliance-Verstoß, der Verkauf bleibt aber bestehen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r3v2', 'de', 'Eine abgelehnte Rechnung blockiert die Transaktion — Waren dürfen rechtlich nicht versendet werden');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r4k', 'de', 'Typische Latenz');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r4v1', 'de', 'Stunden bis wenige Tage');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r4v2', 'de', 'Sekunden bis Minuten');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r5k', 'de', 'Beispiel');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r5v1', 'de', 'Frankreichs E-Reporting für B2C-/grenzüberschreitende Verkäufe');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r5v2', 'de', 'Italiens SDI, Polens KSeF');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.heading', 'de', 'Wo Peppol in dieses Bild passt');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.intro', 'de', 'Peppol wird in diesem Bild leicht falsch eingeordnet — es ist selbst kein Vorgabemodell, sondern ein Stück gemeinsamer Infrastruktur, auf dem mehrere unterschiedliche Modelle aufbauen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.card1.title', 'de', 'Was Peppol tatsächlich ist');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.card1.body', 'de', 'Ein standardisiertes Netzwerk- und Nachrichtenformat (Peppol BIS), das zwei verbundenen Unternehmen den Austausch strukturierter Rechnungen ohne bilaterale Integration ermöglicht — Sie verbinden sich einmal mit einem Access Point, nicht einmal pro Handelspartner.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.card2.title', 'de', 'Reine Infrastruktur, keine Politik');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.card2.body', 'de', 'Belgien und Australien nutzen beide Peppol, aber nur eines von beiden schreibt es heute gesetzlich vor. Das Netzwerk ist dasselbe; was eine Regierung darauf aufsetzt (eine Vorgabe, eine Meldepflicht, gar nichts), ist eine separate Entscheidung.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.card3.title', 'de', 'Die Entwicklung von 4-Corner zu 5-Corner');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.card3.body', 'de', 'Fügen Sie eine fünfte Ecke hinzu — die Steuerbehörde — und dasselbe Netzwerk beginnt, Transaktionsdaten automatisch an die Regierung zu liefern. Singapur, die VAE und die Slowakei arbeiten alle darauf hin.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.flow1', 'de', 'Lieferant');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.flow2', 'de', 'Access Point des Lieferanten');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.flow3', 'de', 'Access Point des Käufers');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.flow4', 'de', 'Käufer');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.heading', 'de', 'Wie es weitergeht');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.intro', 'de', 'Diese Seite ist bewusst die "Landkarte" — für Details zu einem bestimmten Land finden Sie die Einzelheiten in den Länderanalysen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.card1.title', 'de', '🌍 Prüfen Sie das Modell eines bestimmten Landes');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.card1.body', 'de', 'Jede Länderanalyse im Menü "Deep Dives" nennt ihr Compliance-Modell gleich zu Beginn, in denselben Begriffen wie auf dieser Seite — achten Sie auf die Zeile "Compliance model" unter dem Ländernamen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.card2.title', 'de', '🏗️ Sehen Sie, was das für Ihr Unternehmen bedeutet');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.card2.body', 'de', '"Auswirkungen der Vorgabe" (ebenfalls unter Wissen) behandelt die technischen, prozessualen, finanziellen und organisatorischen Auswirkungen dieser Modelle in der Praxis.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.card3.title', 'de', '📖 Weitere Wissensseiten in Vorbereitung');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.card3.body', 'de', 'Tiefere Einblicke in CTC-Untertypen, eine vollständige Karte Peppol-verbundener Länder und ein Überblick über Dienstleister in diesem Bereich sind geplante Ergänzungen dieses Menüs.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.card4.title', 'de', '🔔 Benachrichtigt werden, sobald sie erscheinen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.card4.body', 'de', 'Abonnenten erhalten bevorzugten Zugang zu neuen Wissensinhalten, sobald sie veröffentlicht werden, zusätzlich zum monatlichen Compliance-Digest.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'footer.text', 'de', 'Diese Seite bietet allgemeinen Bildungskontext und stellt keine Rechts- oder Steuerberatung dar. Compliance-Modelle können sich ändern und tun dies auch — die jeweilige Länderanalyse ist die maßgebliche Quelle für ihre aktuellen spezifischen Anforderungen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', '_meta.language', 'de', 'de');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', '_meta.reviewed', 'de', 'true');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'backLink', 'de', '← Zurück zur Übersicht');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'header.eyebrow', 'de', 'Wissen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'header.title', 'de', 'Vorbereitung auf eine Vorgabe');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'header.sub', 'de', 'Sobald Sie das Vorgabemodell und dessen wahrscheinliche Auswirkungen verstehen, lauten die praktischen Fragen: Wer sollte im Raum sein, wie früh sollte das beginnen, und wie gehen Sie die Anbieterauswahl an, ohne es ein Jahr später zu bereuen?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'header.lastUpdated', 'de', 'Zuletzt aktualisiert:');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'stats.label1', 'de', 'Empfohlener Vorlauf vor dem Go-Live');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'stats.label2', 'de', 'Typische Größe der Kernarbeitsgruppe');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'stats.label3', 'de', 'Einer gut durchgeführten Anbieterauswahl');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.heading', 'de', 'Wer einbezogen werden sollte');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.intro', 'de', 'Eine Vorgabenreaktion ohne einen einzigen verantwortlichen Eigentümer, oder bei der die falschen Funktionen im Raum fehlen, ist die häufigste Ursache für späte Überraschungen. Hier ist eine Arbeitsgruppe, die das Terrain abdeckt, ohne unhandlich zu werden.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card1.title', 'de', 'Programmsponsor');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card1.body', 'de', 'Eine leitende Führungskraft aus Finanzen oder Steuern mit der Befugnis, Budget zuzusagen und funktionsübergreifende Meinungsverschiedenheiten zu lösen. Ohne dies kann die Arbeitsgruppe Probleme erkennen, aber nicht immer schnell darauf reagieren.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card2.title', 'de', 'Steuer-/Compliance-Verantwortlicher');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card2.body', 'de', 'Verantwortet die Auslegung der tatsächlichen rechtlichen Anforderung, verfolgt Umfang und Fristen über Einheiten hinweg und pflegt meist die Beziehung zu externen Beratern.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card3.title', 'de', 'IT-/Integrationsverantwortlicher');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card3.body', 'de', 'Bewertet, was die aktuellen ERP-/Kreditoren-/Debitorensysteme nativ leisten können und was nicht, und verantwortet die technische Beziehung zum ausgewählten Anbieter oder zur Plattform.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card4.title', 'de', 'Recht &amp; Datenschutz');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card4.body', 'de', 'Prüft Anbieterverträge, Fragen der Datenresidenz und grenzüberschreitenden Übermittlung — von Anfang an einbezogen statt erst bei Vertragsunterzeichnung, wenn es zu spät ist, die Form des Deals zu beeinflussen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card5.title', 'de', 'Geschäfts-/Einheitsverantwortliche(r)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card5.body', 'de', 'Jemand, der für jedes betroffene Land oder jede Geschäftseinheit verantwortlich ist — besonders wichtig in multinationalen Unternehmen, wo dieselbe Vorgabe je nach lokaler Einheitsstruktur und bestehenden Systemen unterschiedlich ausfallen kann.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card6.title', 'de', 'Einkauf / Anbietermanagement');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card6.body', 'de', 'Führt den formellen Ausschreibungsprozess durch, falls erforderlich, und stellt sicher, dass Vertragsbedingungen (SLAs, Ausstiegsklauseln, Haftung) einer angemessenen kommerziellen Prüfung unterzogen werden, statt als Standardformulierung des Anbieters akzeptiert zu werden.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.outro', 'de', 'Halten Sie diese Gruppe bei 6–8 Personen, die regelmäßig zusammenkommen, mit einem breiteren Kreis (Team-Verantwortliche für Kreditoren/Debitoren, wichtige Kunden oder Anbieter für Tests, externe Berater), der zu bestimmten Meilensteinen konsultiert wird, statt bei jedem Treffen dabei zu sein.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.heading', 'de', 'Wann man beginnen sollte');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.intro', 'de', 'Übergangsfristen und stufenweise Schwellenwerte sind üblich, und es ist verlockend, sie als die eigentliche Frist zu behandeln. In der Praxis dauern Vorlaufzeiten bei Anbietern, Testzyklen und funktionsübergreifende Abstimmung immer länger als erwartet — früh zu beginnen entscheidet tatsächlich darüber, ob der Go-Live ruhig oder chaotisch verläuft.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.marker1', 'de', '12–18 Monate vor dem Go-Live');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.marker2', 'de', '9–12 Monate vor dem Go-Live');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.marker3', 'de', '6–9 Monate vor dem Go-Live');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.marker4', 'de', '3–6 Monate vor dem Go-Live');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.marker5', 'de', '1–3 Monate vor dem Go-Live');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.marker6', 'de', 'Go-Live und danach');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card1.date', 'de', 'Bewertung &amp; Umfangsbestimmung');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card1.badge', 'de', 'Hier beginnen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card1.title', 'de', 'Umfang bestätigen, Arbeitsgruppe bilden, aktuelle Systeme bewerten');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card1.desc', 'de', 'Bestimmen Sie, welche Einheiten tatsächlich betroffen sind und ab wann, bilden Sie die oben genannte Kernarbeitsgruppe, und verschaffen Sie sich ein ehrliches Bild davon, was Ihre aktuellen ERP-/Kreditoren-/Debitorensysteme ohne Hilfe leisten können und was nicht.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card2.date', 'de', 'Anbieterauswahl &amp; Lösungsdesign');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card2.title', 'de', 'Führen Sie den Anbieterauswahlprozess durch (siehe unten) und bestätigen Sie den technischen Ansatz');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card2.desc', 'de', 'Dies ist meist die zeitintensivste Einzelphase — behandeln Sie sie als eigenes Projekt mit eigenem Zeitplan, nicht als schnelle Beschaffungsübung.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card3.date', 'de', 'Aufbau &amp; Integration');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card3.title', 'de', 'Technische Integration, Stammdatenbereinigung, internes Prozessdesign');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card3.desc', 'de', 'Besonders die Stammdatenbereinigung profitiert von einem langen Vorlauf — sie ist selten eine schnelle Lösung, sobald man sich den tatsächlichen Zustand der Kunden-/Lieferantendaten ansieht.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card4.date', 'de', 'Test &amp; Pilot');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card4.title', 'de', 'Sandbox-/Zertifizierungstests, dann ein Live-Pilot mit einer kleinen Transaktionsteilmenge');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card4.desc', 'de', 'Testen Sie gezielt Fehlerpfade — Ablehnungen, Korrekturen, Notfall-/Offline-Modi — nicht nur den Idealfall, in dem alles beim ersten Mal validiert wird.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card5.date', 'de', 'Parallelbetrieb &amp; Umstellungsvorbereitung');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card5.title', 'de', 'Alte und neue Prozesse parallel betreiben, Mitarbeiter an vorderster Front schulen, Notfallpläne finalisieren');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card5.desc', 'de', 'Dies ist auch der Zeitpunkt, Kunden und wichtige Anbieter über anstehende Änderungen zu informieren, falls die Vorgabe beeinflusst, wie sie Rechnungen von/an Sie empfangen oder senden.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card6.date', 'de', 'Stabilisierung');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card6.title', 'de', 'Ablehnungsraten in den ersten Wochen genau überwachen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card6.desc', 'de', 'Ablehnungsraten steigen typischerweise unmittelbar nach dem Go-Live sprunghaft an, da reale Datenrandfälle auftauchen, die Tests nicht erfasst haben — planen Sie hierfür Aufmerksamkeit ein, statt den Go-Live als Ziellinie zu betrachten.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.heading', 'de', 'Planung eines Anbieterauswahlprozesses');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.intro', 'de', 'Ob Sie eine Full-Service-Compliance-Plattform, einen länderspezifischen Vermittler (einen PAC, OSE oder Access Point) oder nur ein Modul innerhalb Ihres bestehenden ERP benötigen — derselbe disziplinierte Prozess zahlt sich aus.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step1.title', 'de', 'Anforderungen definieren, bevor Sie mit einem Anbieter sprechen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step1.body', 'de', 'Benötigte Länder-/Formatabdeckung, erwartetes Transaktionsvolumen, erforderliche Integrationsmethode (API vs. Portal) und Budgetrahmen. Ohne dies an den Markt zu gehen, führt tendenziell zu Angeboten, die schwer fair zu vergleichen sind.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step2.title', 'de', 'Die realistische Anbieterlandschaft kartieren');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step2.body', 'de', 'Optionen umfassen meist globale Full-Service-Compliance-Plattformen, länderspezifische Vermittler und native ERP-Zusatzmodule — jeweils mit unterschiedlichen Abwägungen zwischen Abdeckungsbreite, Tiefe und Kosten.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step3.title', 'de', 'Nach mehr als dem Preis bewerten');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step3.body', 'de', 'Format-/Länderabdeckung, Verfügbarkeits- und Support-SLAs (einschließlich Supportzeiten relativ zu Ihrer Zeitzone), Sicherheitszertifizierungen, erforderlicher Integrationsaufwand auf Ihrer Seite und — entscheidend — ihre Erfolgsbilanz, mit regulatorischen Änderungen in den benötigten Ländern Schritt zu halten.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step4.title', 'de', 'Auf einem Proof of Concept bestehen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step4.body', 'de', 'Ein Sandbox-Test mit Ihren eigenen echten (oder realistischen) Daten deckt Integrationsreibung auf, die eine Verkaufsdemo nie zeigen würde. Behandeln Sie dies vor der Unterzeichnung als nicht verhandelbar, nicht als optionales Extra.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step5.title', 'de', 'Den Vertrag prüfen, nicht nur das Produkt');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step5.body', 'de', 'Datenresidenz-Zusagen, Haftung für Fehler oder verpasste Fristen, Mindest-Fortführungsfristen bei Anbieterwechsel und klare Ausstiegs-/Datenportabilitätsbedingungen — beziehen Sie Recht und Einkauf direkt in dieser Phase ein, nicht als abschließenden Formalakt.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step6.title', 'de', 'Für die nächste Vorgabe planen, nicht nur für diese');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step6.body', 'de', 'Wenn Sie in mehreren Märkten tätig sind, fragen Sie, wie die Roadmap des Anbieters Länder abdeckt, die Sie noch nicht, aber bald benötigen könnten — ein erneuter Anbieterwechsel in zwei Jahren ist ein echter Kostenfaktor, den es zu vermeiden lohnt, wenn eine einzige Beziehung angemessen mit Ihnen wachsen kann.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.heading', 'de', 'Häufige Fallstricke');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.intro', 'de', 'Muster, auf die es sich zu achten lohnt, basierend darauf, wie diese Programme typischerweise schiefgehen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card1.title', 'de', '⏳ Die Übergangsfrist als eigentliche Frist behandeln');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card1.body', 'de', 'Durchsetzungspausen existieren, um den Übergang zu erleichtern, nicht um zu signalisieren, dass keine Dringlichkeit besteht — die zugrunde liegende technische und prozessuale Arbeit muss weiterhin nach dem ursprünglichen Zeitplan erfolgen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card2.title', 'de', '🗂️ Stammdatenbereinigung überspringen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card2.body', 'de', 'Die mit Abstand häufigste Ursache früher Ablehnungen, und das Erste, was unter Zeitdruck nach hinten geschoben wird — es lohnt sich selten, sie zu überspringen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card3.title', 'de', '🙋 Kein einzelner verantwortlicher Eigentümer');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card3.body', 'de', 'Wenn Finanzen, IT und Recht jeweils denken, jemand anderes übernehme die Führung, treten Lücken spät zutage — meist genau dann, wenn keine Zeit mehr bleibt, sie zu beheben.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card4.title', 'de', '🧪 Nur den Idealfall testen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card4.body', 'de', 'Ablehnungen, Korrekturen und Notfall-/Offline-Modi sind genau dort, wo echter operativer Schmerz auftritt — testen Sie diese gezielt, nicht nur den Fall, in dem alles beim ersten Mal funktioniert.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card5.title', 'de', '🌍 Annehmen, dass sich die Lösung eines Marktes auf den nächsten übertragen lässt');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card5.body', 'de', 'Ein Anbieter oder Ansatz, der im Modell eines Landes gut funktioniert, passt nicht automatisch zu dem eines anderen — überprüfen Sie die Eignung Markt für Markt erneut, statt es anzunehmen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card6.title', 'de', '💸 Anbieter anhand von Pilotvolumen-Preisen vergleichen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card6.body', 'de', 'Kostenstrukturen, die bei geringem Volumen ähnlich aussehen, können bei tatsächlichem Produktionsvolumen deutlich auseinanderdriften — modellieren Sie Preise immer in Ihrem tatsächlich erwarteten Maßstab.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.heading', 'de', 'Schnellstart-Checkliste');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q1', 'de', 'Benannter Programmsponsor mit Budgethoheit, bestätigt');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q2', 'de', 'Kernarbeitsgruppe gebildet — Steuern, IT, Recht, Einkauf und betroffene Geschäftseinheiten vertreten');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q3', 'de', 'Umfang bestätigt: welche Einheiten, ab wann, unter welchem Compliance-Modell');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q4', 'de', 'Aktuelle Systemfähigkeit ehrlich bewertet, Lücken dokumentiert');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q5', 'de', 'Anbieteranforderungen dokumentiert, bevor Anbietergespräche beginnen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q6', 'de', 'Proof-of-Concept-Tests vor Vertragsabschluss geplant, nicht danach');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q7', 'de', 'Stammdatenbereinigungsplan in Gang, nicht auf "später" verschoben');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q8', 'de', 'Ablehnungs- und Korrekturworkflows ausdrücklich getestet, nicht angenommen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q9', 'de', 'Schulung der Basisebene (Kreditoren/Debitoren, Auftragserfassung) vor dem Go-Live geplant');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.heading', 'de', 'Wie es weitergeht');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card1.title', 'de', '📘 Nicht sicher, welches Modell gilt?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card1.body', 'de', '"Arten von Vorgaben" (unter Wissen) erklärt die auf dieser Seite genannten Compliance-Modelle.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card2.title', 'de', '🏗️ Verstehen Sie zuerst die vollen Auswirkungen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card2.body', 'de', '"Auswirkungen der Vorgabe" geht tiefer auf die technischen, prozessualen und finanziellen Effekte ein, auf die diese Planungsarbeit letztlich reagiert.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card3.title', 'de', '🌍 Prüfen Sie die Anforderungen Ihres spezifischen Landes');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card3.body', 'de', 'Das Menü der Länderanalysen behandelt die genaue technische Spezifikation, Registrierungsschritte und Sanktionen für jede der 28 hier erfassten Rechtsordnungen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card4.title', 'de', '🏷️ Verstehen Sie zuerst die Anbieterlandschaft');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card4.body', 'de', '"Anbietertypen" (unter Wissen) schlüsselt die fünf im obigen Auswahlprozess genannten Anbieterkategorien auf — ERP, Lösungsanbieter, Steuer-Compliance, Technologie und Beratung.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card5.title', 'de', '✅ Finden Sie einen akkreditierten Anbieter');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card5.body', 'de', '"Staatlich zertifizierte Anbieter" (unter Wissen) verlinkt direkt zu den im obigen Abschnitt zur Anbieterauswahl genannten offiziellen Registern.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'footer.text', 'de', 'Diese Seite bietet allgemeine Bildungshinweise auf Basis gängiger Muster in Programmen zur Vorgabenvorbereitung und stellt keine Rechts-, Steuer- oder Beschaffungsberatung dar. Konkrete Zeitpläne und Anforderungen variieren je nach Land sowie Ihren eigenen Systemen und Ihrer Organisation — konsultieren Sie die jeweilige Länderanalyse und geeignete Berater, bevor Sie sich auf einen Plan festlegen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', '_meta.language', 'de', 'de');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', '_meta.reviewed', 'de', 'true');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'backLink', 'de', '← Zurück zur Übersicht');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'header.eyebrow', 'de', 'Wissen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'header.title', 'de', 'Anbietertypen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'header.sub', 'de', '"Einen Anbieter besorgen" wird der tatsächlichen Vielfalt dieses Marktes nicht gerecht. Fünf grundverschiedene Anbieterkategorien verkaufen allesamt E-Invoicing-Compliance-Lösungen — zu wissen, mit welcher Sie es zu tun haben, ändert, was Sie von ihr erwarten sollten.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'header.lastUpdated', 'de', 'Zuletzt aktualisiert:');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'statusBanner.text', 'de', 'Firmennamen unten sind <strong>rein illustrative Beispiele</strong> — eine kleine, nicht erschöpfende Auswahl, um jede Kategorie greifbar zu machen, keine Empfehlung oder Rangliste. Viele reale Anbieter überschneiden mehr als eine Kategorie.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'stats.label1', 'de', 'Eigenständige Anbieterkategorien');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'stats.label2', 'de', 'Kategorien, die die meisten Programme tatsächlich kombinieren');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'stats.label3', 'de', 'Kategorie, die alles allein abdeckt');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec1.heading', 'de', 'Warum die Kategorie wichtiger ist als der Name');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec1.intro', 'de', 'Zwei Anbieter können beide sagen "wir machen E-Invoicing" und dabei genuin unterschiedliche Dinge meinen. Zu wissen, welche Kategorie Sie bewerten, sagt Ihnen, welche Fragen tatsächlich zu stellen sind — und welche Lücken zu erwarten und einzuplanen sind.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.heading', 'de', 'Die fünf Kategorien');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.strengthsLabel', 'de', 'Typische Stärken');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.tradeoffsLabel', 'de', 'Typische Kompromisse');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.examplesLabel', 'de', 'Illustrative Beispiele:');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card1.title', 'de', '1. ERP-Anbieter');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card1.what', 'de', 'Vollständige Enterprise-Resource-Planning-Suiten — Finanzen, Lieferkette, Personalwesen und mehr —, die E-Invoicing-Compliance als natives oder Zusatzmodul innerhalb ihrer eigenen Plattform aufgebaut haben.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card1.s1', 'de', 'Nativ in Ihrem zentralen Buchführungssystem — keine separate Datenextraktionsebene');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card1.s2', 'de', 'Eine einzige Anbieterbeziehung, wenn Sie bereits Kunde sind');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card1.s3', 'de', 'Konsistente Stammdaten, da sie das ERP nie verlassen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card1.t1', 'de', 'Länderabdeckung und Update-Geschwindigkeit können hinter spezialisierten Anbietern zurückbleiben, besonders bei neueren oder kleineren Märkten');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card1.t2', 'de', 'Oft weiterhin ein Zusatzmodul oder ein Partner für vollständige globale Reichweite nötig');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card1.t3', 'de', 'Weniger flexibel, wenn Sie mehr als ein ERP im Konzern betreiben');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card2.title', 'de', '2. Lösungsanbieter (Kreditoren-/Debitoren-Spezialisten)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card2.what', 'de', 'Anbieter, die sich speziell auf Kreditoren- und Debitorenautomatisierung, E-Rechnungsaustausch konzentrieren und als der akkreditierte Vermittler (Access Point, PAC, OSE) fungieren, den die Vorgabe eines bestimmten Landes verlangt.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card2.s1', 'de', 'Tiefe, oft sich schneller entwickelnde Länder- und Formatabdeckung — das ist ihr gesamtes Geschäft');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card2.s2', 'de', 'ERP-unabhängig — konzipiert, um sich in jedes bereits genutzte System einzuklinken');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card2.s3', 'de', 'Speziell für die Austausch- und Validierungsebene entwickelt');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card2.t1', 'de', 'Eine weitere Anbieterbeziehung und ein weiterer Vertrag neben Ihrem ERP zu verwalten');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card2.t2', 'de', 'Es ist weiterhin Integrationsaufwand nötig, um es an Ihre Kernsysteme anzubinden');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card3.title', 'de', '3. Steuer-Compliance-Anbieter');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card3.what', 'de', 'Anbieter, deren Kerngeschäft die breitere indirekte Steuer-Compliance ist — Umsatzsteuer-/GST-Bestimmung, Erklärungen und Meldungen —, die sich als Teil dieses breiteren Steuertechnologie-Stacks auf E-Invoicing ausgeweitet haben.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card3.s1', 'de', 'Ein Anbieter für sowohl Steuerbestimmung als auch E-Invoicing, wenn Sie ihn bereits für Steuern nutzen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card3.s2', 'de', 'Tiefe steuertechnische Expertise, die der Compliance-Logik zugrunde liegt');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card3.t1', 'de', 'E-Invoicing kann ein neuerer Teil ihres Angebots sein als ihr Kernsteuerprodukt — prüfen Sie die Reife der Länderabdeckung hierfür spezifisch, nicht nur ihren allgemeinen Steuerruf');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card4.title', 'de', '4. Technologieanbieter (EDI / Middleware)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card4.what', 'de', 'Anbieter, deren Kernkompetenz der breitere B2B-Datenaustausch und Integrations-Middleware ist — oft seit langem in EDI etabliert —, die strukturierte E-Rechnungsformat-Unterstützung als Erweiterung dieser bestehenden Fähigkeit hinzugefügt haben.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card4.s1', 'de', 'Wenn Sie bereits erhebliches EDI-Handelspartnervolumen betreiben, wird dieselbe Integrationsebene erweitert, statt ein Parallelsystem hinzuzufügen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card4.s2', 'de', 'Starke universelle Fähigkeiten zur Datenzuordnung und -transformation');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card4.t1', 'de', 'CTC-spezifische Feinheiten — Echtzeit-Freigabe, digitale Signaturen, staatliche Meldungen — sind oft eine neuere Schicht auf einer EDI-first-Architektur, nicht Teil der Kern-DNA');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card5.title', 'de', '5. Beratungsunternehmen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card5.what', 'de', 'Beratungs- und Umsetzungsfirmen — selbst kein Softwareprodukt —, die Bewertung, Unterstützung bei der Anbieterauswahl und Programmmanagement für eine Vorgabenreaktion anbieten.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card5.s1', 'de', 'Unabhängig von einem einzelnen Softwareanbieter, was objektivere Unterstützung bei der Anbieterauswahl bedeuten kann');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card5.s2', 'de', 'Nützlich für komplexe, länder- und einheitenübergreifende Programme, die dediziertes Programmmanagement benötigen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card5.t1', 'de', 'Ersetzt nicht die Notwendigkeit eines tatsächlichen Software-/Dienstanbieters — dies ist eine ergänzende Ebene');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card5.t2', 'de', 'Typischerweise Kosten nach Zeit und Aufwand statt einer vorhersehbaren Gebühr pro Transaktion');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.heading', 'de', 'Im Vergleich');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.intro', 'de', 'Ein grober Leitfaden dazu, wie sich die Kategorien typischerweise unterscheiden — reale Anbieter variieren, und mehrere überschneiden bewusst mehr als eine Zeile.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.h1', 'de', 'Kategorie');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.h2', 'de', 'Kerngeschäft');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.h3', 'de', 'Tiefe der Länderabdeckung');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.h4', 'de', 'Typisches Kostenmodell');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r1c1', 'de', 'ERP-Anbieter');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r1c2', 'de', 'Vollständiges Geschäftssystem, E-Invoicing als Modul');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r1c3', 'de', 'Unterschiedlich — stark in Heimatmärkten, kann anderswo hinterherhinken');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r1c4', 'de', 'Lizenzierung + Modulgebühren');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r2c1', 'de', 'Lösungsanbieter');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r2c2', 'de', 'Kreditoren-/Debitorenautomatisierung &amp; E-Rechnungsaustausch');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r2c3', 'de', 'Meist breit — das ist ihre Spezialität');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r2c4', 'de', 'Pro Transaktion oder Abonnement');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r3c1', 'de', 'Steuer-Compliance-Anbieter');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r3c2', 'de', 'Bestimmung und Einreichung indirekter Steuern');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r3c3', 'de', 'Stark, wo ihr Steuerprodukt etabliert ist');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r3c4', 'de', 'Abonnement, oft mit Steuerprodukt gebündelt');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r4c1', 'de', 'Technologieanbieter');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r4c2', 'de', 'B2B-Datenaustausch / EDI-Middleware');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r4c3', 'de', 'Stark, wo EDI-Handel bereits etabliert ist');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r4c4', 'de', 'Pro Transaktion oder Plattformgebühr');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r5c1', 'de', 'Beratungsunternehmen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r5c2', 'de', 'Beratungs- &amp; Umsetzungsdienstleistungen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r5c3', 'de', 'Beratungsreichweite, keine technische Plattform selbst');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r5c4', 'de', 'Zeit-und-Aufwand- oder Festpreisprojekt');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec4.heading', 'de', 'Wie sich diese in der Praxis tatsächlich kombinieren');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec4.intro', 'de', 'Nur sehr wenige reale Vorgabenprogramme nutzen nur eine Kategorie — die meisten kombinieren zwei oder drei, jede deckt einen anderen Teil des Problems ab.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec4.scenarioTitle', 'de', 'Ein realistisches multinationales Szenario');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec4.scenarioBody', 'de', 'Ein Konzern, der SAP global betreibt, nutzt das native Compliance-Modul seines ERP für Märkte mit ausgereifter Abdeckung, holt einen spezialisierten Lösungsanbieter gezielt für eine Handvoll Länder hinzu, die das ERP-Modul noch nicht gut unterstützt, und beauftragt für einige Monate ein Beratungsunternehmen, um das Programmmanagement über den gesamten Rollout zu führen und die Anbieterauswahl zu unterstützen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec4.flow1', 'de', 'ERP-Modul — reife Märkte');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec4.flow2', 'de', 'Lösungsanbieter — Abdeckungslücken');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec4.flow3', 'de', 'Beratung — Programmaufsicht');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec5.heading', 'de', 'Fragen, die sich lohnen, unabhängig davon, welche Kategorie Sie bewerten');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec5.q1', 'de', 'Ist E-Invoicing für diesen Anbieter genuin Kerngeschäft, oder ein Zusatz zu etwas anderem, das er verkauft?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec5.q2', 'de', 'Wie schnell haben sie historisch Unterstützung für neu angekündigte Vorgaben hinzugefügt?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec5.q3', 'de', 'Halten sie die Akkreditierung direkt, oder verlassen sie sich für bestimmte Länder auf einen Dritten unter ihnen?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec5.q4', 'de', 'Wenn sie Spezialist in einer Kategorie sind, wen erwarten sie, dass Sie hinzuziehen, um die anderen abzudecken?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec5.q5', 'de', 'Wie sieht ihre Roadmap für Länder aus, die Sie noch nicht benötigen, aber in ein bis zwei Jahren vielleicht?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec6.heading', 'de', 'Weiterführend: Analystenforschung');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec6.intro', 'de', 'Fünf Analysehäuser decken diesen Markt aktiv ab und sind es wert, gekannt zu werden, wenn Sie unabhängige Validierung jenseits der Aussagen eines einzelnen Anbieters wünschen. Die meisten vollständigen Berichte liegen hinter einem Abonnement oder einem vom Anbieter bereitgestellten Auszug, aber jedes Haus unten veröffentlicht auch etwas genuin frei Zugängliches ohne ein solches.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec6.gartner', 'de', 'Veröffentlicht jährlich einen Magic Quadrant für Accounts Payable Applications, zusammen mit einer eigenen Kategorie "E-invoicing Compliance Applications" auf Gartner Peer Insights — echte, durchsuchbare Nutzerbewertungen, kein Abonnement erforderlich.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec6.forrester', 'de', 'Veröffentlicht regelmäßig The Forrester Wave™: Accounts Payable Invoice Automation Software (zuletzt Q2 2026). Die vollständige Wave erfordert Forrester-Zugang, aber die eigene Blog-Ankündigung mit einer Zusammenfassung der Erkenntnisse jeder Ausgabe ist öffentlich lesbar.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec6.idc', 'de', 'Veröffentlicht IDC-MarketScape-Anbieterbewertungen zu E-Invoicing- und Umsatzsteuer-Compliance-Software, sowohl weltweite als auch europaspezifische Ausgaben. Die vollständigen Bewertungen sind kostenpflichtig, aber IDCs eigene Blogserie zu E-Invoicing ist ein genuin nützlicher, frei zugänglicher Einstiegspunkt.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec6.spendMatters', 'de', 'Betreibt SolutionMap, ein Ranking-System, das Beschaffungstechnologie in 16 Source-to-Pay-Kategorien abdeckt, einschließlich Kreditorenautomatisierung. Erwähnenswert: Spend Matters ist nach einer Fusion nun eine Abteilung der Hackett Group, sodass beide zunehmend eine Forschungsorganisation sind statt vollständig unabhängig voneinander.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec6.hackett', 'de', 'Führt groß angelegte Benchmarking-Studien zu Procure-to-Pay- und Kreditorenbuchhaltungs-Leistung durch, einschließlich spezifischer Forschung dazu, wie KI Kreditorenlösungen und die globale E-Invoicing-/CTC-Compliance-Fähigkeit verändert.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec6.footnote', 'de', 'Bestimmte namentlich genannte Ausgaben (z. B. "Q2 2026") werden in regelmäßigen Zyklen abgelöst — prüfen Sie die eigene Website jedes Hauses auf die aktuelle Version, statt anzunehmen, dass eine hier oder anderswo genannte konkrete Ausgabe zum Zeitpunkt Ihrer Lektüre noch die aktuellste ist.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec7.heading', 'de', 'Wie es weitergeht');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec7.card1.title', 'de', '🗓️ Den eigentlichen Auswahlprozess durchführen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec7.card1.body', 'de', '"Vorbereitung auf eine Vorgabe" (unter Wissen) behandelt, wie Anforderungen definiert, ein Proof of Concept durchgeführt und ein Vertrag geprüft werden, sobald Sie wissen, welche Kategorie passt.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec7.card2.title', 'de', '✅ Staatlich verifizierte Anbieter prüfen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec7.card2.body', 'de', '"Staatlich zertifizierte Anbieter" verlinkt direkt zu offiziellen Registern, in denen mehrere Länder akkreditierte Anbieter namentlich veröffentlichen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec7.card3.title', 'de', '🌍 Prüfen Sie die Anforderungen Ihres spezifischen Landes');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec7.card3.body', 'de', 'Das Menü der Länderanalysen behandelt die genauen technischen Spezifikationen und Registrierungsschritte für jede der 28 hier erfassten Rechtsordnungen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'footer.text', 'de', 'Firmennamen auf dieser Seite sind rein illustrative Beispiele, um jede Kategorie greifbar zu machen — sie sind keine Empfehlungen, Ranglisten oder eine vollständige Marktübersicht, und ihre Nennung impliziert keine Beziehung zu dieser Website. Die oben genannte Analystenforschung wird nur zur allgemeinen Information verlinkt; vollständige Berichte können ein kostenpflichtiges Abonnement oder anbieterseitigen Zugang erfordern, und jede darin enthaltene Anbieterpositionierung spiegelt die eigene Methodik und Ansichten dieses Hauses wider, nicht unsere. Prüfen Sie die aktuelle Akkreditierung und Eignung eines bestimmten Anbieters für Ihre Bedürfnisse direkt, bevor Sie ihn beauftragen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('feedback', '_meta.language', 'de', 'de');
INSERT INTO translations (namespace, key, lang, value) VALUES ('feedback', '_meta.reviewed', 'de', 'true');
INSERT INTO translations (namespace, key, lang, value) VALUES ('feedback', 'backLink', 'de', '← Zurück zur Übersicht');
INSERT INTO translations (namespace, key, lang, value) VALUES ('feedback', 'form.eyebrow', 'de', 'Eine Lücke oder einen Fehler entdeckt?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('feedback', 'form.title', 'de', 'Feedback senden');
INSERT INTO translations (namespace, key, lang, value) VALUES ('feedback', 'form.sub', 'de', 'Fehlt ein Land, ist ein Datum veraltet, oder ist ein Portal-Link defekt? Lassen Sie es uns wissen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('feedback', 'form.emailLabel', 'de', 'E-Mail-Adresse');
