INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.eyebrow', 'de', 'Nie wieder überrascht werden');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.title', 'de', 'Erfahren Sie sofort, wenn eine Regierung die Regeln ändert');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.intro', 'de', 'E-Invoicing-Schwellenwerte, Wellen-Nummern und Stichtage ändern sich ständig — oft mit wenig öffentlicher Vorankündigung. Einmal abonniert, landet jede Regierungsaktualisierung oder -ankündigung aus den 28 von uns erfassten Rechtsordnungen automatisch in Ihrem Posteingang, in klarer Sprache, bevor sie Ihr Team überrascht.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.sampleLink', 'de', '👀 Echte Beispielausgabe ansehen (Januar 2026) →');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.stat1', 'de', 'Erfasste Rechtsordnungen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.stat2', 'de', 'Versandrhythmus');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.stat3', 'de', 'Spam zwischen den Ausgaben');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item1.title', 'de', 'Echte Regierungsankündigungen, zusammengefasst');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item1.body', 'de', 'Jede neue Vorgabe, jede verschobene Frist und jede Sanktionsänderung, die wir erfassen, in klarer Sprache geschrieben — kein Rechtstext, der aus einer Pressemitteilung der Steuerbehörde kopiert wurde.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item2.title', 'de', 'Wählen Sie genau die Länder, die Sie interessieren');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item2.body', 'de', 'Teilen Sie uns mit, welche der 28 Rechtsordnungen für Ihr Unternehmen relevant sind, und Ihre monatliche Benachrichtigungs-E-Mail sagt Ihnen konkret, ob sie vorkamen — oder erhalten Sie den vollständigen globalen Digest, wenn Sie lieber alles sehen möchten.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item3.title', 'de', 'Ein vollständiges, durchsuchbares Archiv');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item3.body', 'de', 'Jede vergangene Ausgabe liegt in einem durchsuchbaren, filterbaren Archiv — schauen Sie jederzeit auf jeden Monat, jedes Land zurück, nicht nur auf das, was zuletzt in Ihrem Posteingang landete.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item4.title', 'de', 'Bevorzugter Zugang zu neuen Wissensinhalten');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item4.body', 'de', 'Neue Länderanalysen und Wissensleitfäden werden Abonnenten zuerst angezeigt, sobald wir sie veröffentlichen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.eyebrow', 'de', 'Abonnieren');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.title', 'de', 'Los geht''s');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.sub', 'de', 'Eine E-Mail pro Monat, plus eine kurze Benachrichtigung, wann immer eine neue Ausgabe zu Ihren Ländern erscheint. Ob wiederkehrend oder einmalig, wählen Sie im nächsten, sicheren Schritt.');
