INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.countriesLabel', 'de', 'Für welche Länder möchten Sie Benachrichtigungen erhalten?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.countriesHint', 'de', 'Optional — lassen Sie alles unmarkiert, und wir senden Ihnen den vollständigen monatlichen Digest für alle 28 Rechtsordnungen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.countriesMissing', 'de', 'Die Länderauswahl ist vorübergehend nicht verfügbar — Sie erhalten trotzdem den vollständigen monatlichen Digest. (Fehlende Datei: countries.js)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.selectAll', 'de', 'Alle auswählen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.clearAll', 'de', 'Alle abwählen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.submitButton', 'de', 'Weiter zur sicheren Zahlung');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.fineprint', 'de', 'Die Zahlung wird von Lemon Squeezy, unserem Handelsvertreter, abgewickelt — sie erheben und führen jede anfallende Umsatzsteuer/GST für diesen Verkauf ab, sodass Ihnen nie separat Steuern berechnet werden. Wir sehen oder speichern Ihre Kartendaten niemals. Siehe unsere <a href="privacy-policy.html" style="color:#b5432f; text-decoration:underline;">Datenschutzerklärung</a>, um zu erfahren, wie Ihre Daten verarbeitet werden.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'confirm.eyebrow', 'de', 'Noch ein Schritt');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'confirm.title', 'de', 'Bestätigen Sie Ihre Angaben');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'confirm.subscribingAs', 'de', 'Abonnieren als');
