INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'confirm.fullDigest', 'de', 'den vollständigen Digest (alle 28 Rechtsordnungen)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'confirm.fineprint', 'de', 'Sie werden zu einem sicheren Lemon-Squeezy-Zahlungsfenster weitergeleitet, in dem Sie zwischen wiederkehrender und einmaliger Zahlung wählen und Ihren Kauf abschließen können.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'confirm.payButton', 'de', 'Weiter zur Zahlung →');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'confirm.editLink', 'de', '← Meine Angaben bearbeiten');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'modal.close', 'de', '✕ Schließen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'modal.badge', 'de', 'Echte Beispielausgabe — kein Mockup');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'modal.fineprint', 'de', 'Dies ist die tatsächliche erste Ausgabe, die an Abonnenten gesendet wurde, genau wie veröffentlicht — nichts wurde für diese Vorschau bearbeitet oder gekürzt. Jeder Abonnent erhält Zugang zum vollständigen durchsuchbaren Archiv, nicht nur zu dieser einen Ausgabe.');
