INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'brand.eyebrow', 'de', 'Compliance-Übersicht');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'brand.title', 'de', 'The E-Invoicing<br>Compliance Corner');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'brand.description', 'de', 'Ein laufend aktualisierter Überblick über E-Invoicing- und digitale Meldepflichten in 28 Ländern — EU-weite ViDA-Regeln, nationale CTC-Systeme und alles dazwischen. Jeder Eintrag zeigt die Frist, was konkret zu tun ist, und einen direkten Link zum offiziellen Regierungsportal — damit Sie in einem einzigen Blick von "betrifft uns das?" zu "das müssen wir tun" kommen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'perks.heading', 'de', 'Abonnenten erhalten außerdem');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'perks.item1', 'de', 'Einen monatlichen E-Mail-Digest — jede neue Vorgabe oder Friständerung, zusammengefasst');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'perks.item2', 'de', 'Vollen Zugriff auf das Newsletter-Archiv, nicht nur die aktuelle Ausgabe');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'perks.item3', 'de', 'Bevorzugten Zugang zu neuen Länder-Deep-Dives, sobald sie veröffentlicht werden');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'perks.item4', 'de', 'Verständliche Zusammenfassungen, was das für Ihr Team bedeutet — nicht nur Gesetzestext');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'perks.cta', 'de', 'Abonnieren (Demnächst) →');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.label', 'de', 'So funktioniert diese Seite');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip1Title', 'de', 'Filtern Sie auf das Wesentliche');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip1Desc', 'de', 'Nutzen Sie die Region- und Status-Filter oder die Suche, um die Zeitleiste auf Ihre Märkte einzugrenzen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip2Title', 'de', 'Tiefer in ein Land einsteigen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip2Desc', 'de', 'Das Menü "Deep Dives" verlinkt zu einer vollständigen technischen Analyse — Dateiformate, Übertragungsprotokolle, Registrierungsschritte und Strafen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip3Title', 'de', 'Direkt zum Portal springen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip3Desc', 'de', 'Die Seitenleiste (☰ auf Mobilgeräten) verlinkt direkt zum offiziellen Regierungsportal jedes hier erfassten Landes.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip4Title', 'de', 'Altes ist eingeklappt');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip4Desc', 'de', 'Die Zeitleiste zeigt standardmäßig aktuelle und bevorstehende Änderungen — längst etablierte Vorschriften finden Sie im eingeklappten Bereich weiter unten.');
