INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'about.eyebrow', 'de', 'Über uns');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'about.title', 'de', 'The E-Invoicing Compliance Corner');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'about.p1', 'de', 'The E-Invoicing Compliance Corner entstand als Antwort auf die wachsende Komplexität und die rasante Verbreitung von E-Invoicing-Vorgaben weltweit. Ob kleines Unternehmen oder globaler Konzern — dieses Thema kann schwierig und teuer in der Umsetzung sein.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'about.p2', 'de', 'Diese Seite soll einen kostengünstigen, einfachen Zugang zu verlässlichen Informationen bieten — und Sie laufend benachrichtigen, sobald sich Vorgaben ändern oder neue Gesetze eingeführt werden.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'languageSwitcher.label', 'de', 'Sprache');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'languageSwitcher.unreviewedBanner', 'de', 'Diese Übersetzung wurde mit KI-Unterstützung erstellt und noch nicht von einem menschlichen Übersetzer geprüft. Die Formulierung kann ungenau sein — bei Unklarheiten bitte die englische Version heranziehen.');
