INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'filters.footerNote', 'de', 'Daten aus offiziellen Quellen der Steuerbehörden und der Europäischen Kommission zusammengestellt. "Verbleibende Tage" und Status-Kennzeichnungen werden automatisch anhand des heutigen Datums berechnet. <a href="privacy-policy.html" style="color:var(--soon);">Datenschutzerklärung</a>');
