INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'filters.noUpcoming', 'de', 'Keine bevorstehenden Meilensteine im erfassten Datensatz.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'filters.disclaimer', 'de', 'Dieser Tracker spiegelt öffentlich verfügbare Hinweise mit Stand Juli 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Schwellenwerte, Wellen-Nummern und Stichtage für E-Invoicing ändern sich häufig — bestätigen Sie Ihre Pflichten direkt auf dem in jedem Eintrag verlinkten offiziellen Regierungsportal oder bei Ihrem Steuerberater, bevor Sie Compliance-Entscheidungen treffen.');
