INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'filters.recentIntro', 'de', 'Meilensteine der letzten Monate bis zur am weitesten entfernten bestätigten Frist. Bereits etablierte Vorschriften befinden sich im eingeklappten Bereich weiter unten, damit diese Liste auf das Aktuelle fokussiert bleibt.');
