INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', '_meta.language', 'en', 'en');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', '_meta.reviewed', 'en', 'true');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'backLink', 'en', '← Back to global tracker');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'header.eyebrow', 'en', 'Education');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'header.title', 'en', 'Government Certified Providers');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'header.sub', 'en', 'Where to find the official, government-published list of accredited service providers or Peppol-ready software for each country — verified directly against the relevant authority''s own site, not a third-party summary.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'header.lastUpdated', 'en', 'Last updated:');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'statusBanner.text', 'en', 'This is a <strong>starting set of verified links</strong>, not a complete map of all 28 tracked jurisdictions. Every link below was checked directly against the named government/authority''s own website. Several countries in this tracker don''t run a public accreditation registry at all — see the note in Section 3 before assuming one exists.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'stats.label1', 'en', 'Countries verified so far');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'stats.label2', 'en', 'Different accreditation terms in use');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'stats.label3', 'en', 'Global Peppol provider directory');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec1.heading', 'en', 'Same idea, different names');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec1.intro', 'en', 'Every country below runs a version of the same concept — a government-recognised list of software or intermediaries you can safely rely on — but each one uses its own term for it.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec1.card1.body', 'en', 'Used in the UAE. The intermediary that validates and transmits your e-invoices over the Peppol network on your behalf.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec1.card2.body', 'en', 'Used in Mexico. The third party authorised by SAT to stamp (timbrar) your CFDI and give it legal validity.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec1.card3.body', 'en', 'Used in Peru. An OSE validates your invoice with the same legal authority as SUNAT itself; a PSE signs on your behalf using its own certificate.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec1.card4.body', 'en', 'Used in India. A licensed intermediary providing the software/API layer that connects a taxpayer to the GSTN.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec1.card5.title', 'en', 'Peppol Service Provider / Access Point');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec1.card5.body', 'en', 'Used in Malaysia, Singapore, Australia, and any other Peppol-based market. An accredited Access Point connects your business to the shared Peppol network.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.heading', 'en', 'Verified official links, by country');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.intro', 'en', 'Click through to the authority''s own page — always cross-check a specific provider''s current status there directly before signing anything, since these lists change.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.h1', 'en', 'Country');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.h2', 'en', 'What''s listed');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.h3', 'en', 'Official source');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.uae', 'en', 'Ministry of Finance''s register of pre-approved / accredited e-invoicing Service Providers (ASPs)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.mexico', 'en', 'SAT''s register of Proveedores Autorizados de Certificación');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.peru', 'en', 'SUNAT''s official padrón (registry) of authorised OSE and PSE providers');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.india', 'en', 'GSTN''s list of licensed GST Suvidha Providers');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.malaysia', 'en', 'MDEC''s (Malaysia''s Peppol Authority) register of accredited Peppol Service Providers');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.singapore', 'en', 'IMDA''s list of authorised Access Point providers and InvoiceNow-Ready solutions');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.australia', 'en', 'The ATO''s (Australian Peppol Authority) register of accredited Peppol service providers');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.france', 'en', 'The DGFiP''s list of registered Plateformes Agréées (formerly PDP)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.franceNote', 'en', 'France''s exact list sits within the DGFiP''s broader impots.gouv.fr site rather than one fixed, stable URL we could verify with full confidence — search "liste des plateformes agréées" directly on that site for the current version.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec3.heading', 'en', 'Where this pattern doesn''t apply');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec3.intro', 'en', 'Several major markets in this tracker simply don''t run a public provider-accreditation registry at all — worth knowing so you don''t go looking for one that doesn''t exist.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec3.card1.body', 'en', 'KSeF and SDI are both direct government platforms — any compliant software can connect via the published API/schema, with no formal "accredited intermediary" layer to certify against.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec3.card2.body', 'en', 'Taxpayers self-certify as authorised issuers directly with the tax authority (SEFAZ, SII); there''s no equivalent PAC/OSE-style third-party accreditation model in either country.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec3.card3.body', 'en', 'ZATCA doesn''t publish a comparable public list — compliance is a matter of your invoicing system meeting the published technical specification directly, not intermediary accreditation.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec4.heading', 'en', 'One resource that spans every Peppol market');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec4.body', 'en', 'For any Peppol-based country not yet in the table above — Belgium, Norway, Denmark, and others — OpenPeppol itself (the network''s governing body) maintains a single global register of every certified Peppol service provider, searchable by country of legal residence.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.heading', 'en', 'Where to go next');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.card1.title', 'en', '🏷️ Understand the vendor categories first');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.card1.body', 'en', '"Types of Provider" (under Education) breaks down ERP, Solution Provider, Tax Compliance, Technology, and Consultancy categories before you start browsing government lists.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.card2.title', 'en', '🗓️ Ready to run a vendor selection?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.card2.body', 'en', '"Preparing for a Mandate" (under Education) walks through how to evaluate and select a provider once you''ve found the right list.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.card3.title', 'en', '🌍 Check your country''s specific requirements');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.card3.body', 'en', 'The Deep Dives menu covers exact registration steps, technical specifications, and penalties for each of the 28 jurisdictions tracked here.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.card4.title', 'en', '📬 This list will grow');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.card4.body', 'en', 'More countries will be added here as we verify their official sources directly — subscribers get notified when new entries are published.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'footer.text', 'en', 'This page links directly to official government and authority sources as verified at the date above, and is provided for general awareness — it is not an endorsement of any specific provider, and inclusion on a government list is not a guarantee of fit for your specific needs. Always confirm a provider''s current accreditation status directly on the linked official page before signing an agreement.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', '_meta.language', 'en', 'en');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', '_meta.reviewed', 'en', 'true');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'backLink', 'en', '← Back to global tracker');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'header.eyebrow', 'en', 'Education');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'header.title', 'en', 'Impact of Mandate');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'header.sub', 'en', 'A new e-invoicing mandate rarely stays inside IT. This page walks through where the impact actually lands across a business — technical, procedural, financial, and organisational — so you can scope the real project, not just the software purchase.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'header.lastUpdated', 'en', 'Last updated:');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'stats.label1', 'en', 'Functions typically involved');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'stats.label2', 'en', 'Some issuance windows, down from days');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'stats.label3', 'en', 'Rejected invoice can block a shipment');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.heading', 'en', 'Why this is bigger than an IT project');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.intro', 'en', 'The most common mistake in scoping a mandate response is treating it as "connect our ERP to a new format." In practice, most mandates touch at least five functions simultaneously — and each one discovers its piece of the work at a different time, usually too late.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.card1.title', 'en', 'Finance &amp; Tax');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.card1.body', 'en', 'Owns the compliance obligation itself, and usually the relationship with the chosen platform/intermediary — but often lacks visibility into whether the ERP can actually produce what''s required.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.card2.title', 'en', 'IT');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.card2.body', 'en', 'Builds the integration, but is frequently brought in only once Finance has already committed to a deadline — leaving little room to influence scope or timeline.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.card3.title', 'en', 'Legal &amp; Data Protection');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.card3.body', 'en', 'Needs to weigh in on data residency, cross-border transfer, and contractual terms with new intermediaries — often the last function consulted, when it should be one of the first.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.card4.title', 'en', 'Sales, Procurement &amp; Logistics');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.card4.body', 'en', 'Capture the master data (tax IDs, classification codes, addresses) that clearance systems now validate strictly — and are the ones who feel it operationally when a shipment gets stuck behind a rejected invoice.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.heading', 'en', 'Technical impact');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.intro', 'en', 'This is usually where planning starts — and where the real complexity is easiest to underestimate, especially once more than one jurisdiction is involved.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card1.title', 'en', 'Integration approach');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card1.body', 'en', 'Direct ERP-to-platform API integration, a middleware/service-provider layer (PAC, OSE, Access Point), or a manual web-portal fallback for low volumes — each has a different cost, speed, and maintenance profile.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card1.note', 'en', 'The "manual portal" option often looks free at low volume, then becomes the bottleneck the moment volume grows — model both.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card2.title', 'en', 'Format fragmentation');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card2.body', 'en', 'There is no universal e-invoice format. UBL, CII, JSON, and country-specific schemas (CFDI, FA(3), e-fapiao) all coexist — a business operating across several mandated markets is realistically maintaining several different technical integrations, not one.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card3.title', 'en', 'Master data quality');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card3.body', 'en', 'Clearance systems validate tax IDs, product/service classification codes, and buyer details in real time. Data that was "good enough" for an internal ERP field often fails validation the first time it meets a government platform.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card3.note', 'en', 'This is consistently the single largest source of early rejections — worth a dedicated data-cleansing pass before go-live, not after.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card4.title', 'en', 'Digital certificates &amp; signing');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card4.body', 'en', 'Many regimes require a qualified digital certificate to sign invoices or authenticate API calls. Certificates expire, need renewal processes, and sometimes need delegating to a third-party provider — a genuine ongoing administrative task, not a one-time setup step.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card5.title', 'en', 'Resilience &amp; contingency');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card5.body', 'en', 'What happens when the government platform is down? Several regimes define explicit offline/contingency modes (Poland''s Offline24, Saudi Arabia''s failure mode) — building for these from day one avoids a scramble the first time it actually happens.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card6.title', 'en', 'Archiving obligations');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card6.body', 'en', 'Retention periods for e-invoices are often longer, and more format-specific, than general accounting record rules (10 years is common; some categories run longer). The original structured file — not a printed or PDF rendering — is usually what must be preserved.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.heading', 'en', 'Data residency &amp; sovereignty');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.intro', 'en', 'Easy to miss if invoicing is centralised in a shared service centre — a mandate in one country can have implications for where and how that data is allowed to be processed.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.card1.title', 'en', 'Where does the data actually sit?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.card1.body', 'en', 'Some clearance models route invoice content through government infrastructure or locally accredited intermediaries by design — worth checking whether your chosen provider processes and stores data within the country in question, or elsewhere.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.card2.title', 'en', 'Shared service centre conflicts');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.card2.body', 'en', 'A common architecture — invoicing for many countries processed centrally from one hub — can collide with a specific country''s expectation that certain data stays local. Worth checking explicitly, market by market, rather than assuming a global platform is automatically fine everywhere.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.card3.title', 'en', 'Increased government visibility');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.card3.body', 'en', 'Clearance and real-time reporting models give tax authorities far more granular, near-live visibility into commercial transactions than periodic filing ever did. Some businesses raise this as a genuine competitive-sensitivity concern worth flagging to leadership, even where it doesn''t change the compliance obligation itself.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.card4.title', 'en', 'Provider lock-in risk');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.card4.body', 'en', 'Country-specific intermediaries (a particular PAC, OSE, or Access Point) can become quietly load-bearing infrastructure. Understand your exit/migration path before you''re dependent on one — some regimes even mandate a minimum continuity period from providers for exactly this reason.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.heading', 'en', 'Process &amp; document workflow changes');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.intro', 'en', 'The part that catches finance teams out hardest: familiar document workflows — credit notes, debit notes, corrections — don''t always survive a mandate unchanged.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.h1', 'en', 'Old process');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.h2', 'en', 'What changes under many mandates');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r1k', 'en', 'Issue a credit/debit note freely to correct an error');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r1v', 'en', 'A formal "corrective invoice" process instead, often with its own document type and validation rules — some regimes no longer accept ad hoc correction notes at all (Poland''s KSeF retired the traditional "nota korygująca" in favour of structured corrections through the platform itself)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r2k', 'en', 'Edit or cancel an issued invoice directly');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r2v', 'en', 'Once cleared/reported, many invoices legally can''t be edited — the only path is a formal credit note or a new corrective document, even for minor errors');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r3k', 'en', 'Batch invoices at month-end');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r3v', 'en', 'Issuance windows now measured in hours or days (24 hours in Saudi Arabia for B2C reporting; 5 working days in Romania and Slovakia) force closer-to-real-time issuance');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r4k', 'en', 'Assume an invoice is valid once sent');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r4v', 'en', 'A rejected invoice in a clearance model has no legal effect at all — in practice this can hold up shipment of goods until it''s resolved, a supply-chain problem, not just an accounting one');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r5k', 'en', 'Buyer accepts an invoice implicitly');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r5v', 'en', 'Some regimes give buyers an active accept/reject window (Malaysia: 72 hours) — silence isn''t automatically acceptance, and missing that window can force a full credit/debit note instead of a simple cancellation');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.heading', 'en', 'Financial &amp; commercial impact');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.intro', 'en', 'Beyond the direct cost of compliance software, there are second-order effects worth putting in front of finance leadership early.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.card1.title', 'en', 'Compliance cost structure');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.card1.body', 'en', 'Per-transaction fees from intermediaries, software licensing, certificate costs, and integration work all scale differently — a cost model that looks fine at pilot volume can look very different at full production volume. Model it at scale before committing to a provider.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.card2.title', 'en', 'Cash flow, both ways');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.card2.body', 'en', 'Some regimes reward compliant e-invoicing with faster payment terms (5-day payment targets in New Zealand and Australia''s public sector). But a rejected or delayed clearance can just as easily hold up payment — the same mechanism cuts both directions.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.card3.title', 'en', 'Your customer''s exposure, not just yours');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.card3.body', 'en', 'In many regimes, a non-compliant invoice from you can block your customer''s own input VAT deduction or expense claim. This turns your compliance gap into their financial problem — a real relationship risk, not just an internal one.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.card4.title', 'en', 'Market entry friction');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.card4.body', 'en', 'Entering a new mandated market isn''t just a sales decision anymore — you may need local registration, an intermediary relationship, and technical integration in place before you can legally invoice a single customer there.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.heading', 'en', 'Organisational readiness');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.intro', 'en', 'The softest impact area, and often the one that determines whether the technical rollout actually goes smoothly.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.card1.title', 'en', 'One programme, not five projects');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.card1.body', 'en', 'Finance, IT, Legal, and Sales/Procurement each discovering the mandate independently, on their own timeline, is a recipe for late surprises. A single cross-functional owner materially reduces this risk.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.card2.title', 'en', 'Tracking group/subsidiary scope');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.card2.body', 'en', 'Many mandates phase in by revenue threshold, sometimes calculated across a whole corporate group rather than per entity (as in New Zealand''s and Malaysia''s rules). Legal and Finance need a shared, current view of group structure to know who''s actually in scope, and when.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.card3.title', 'en', 'Frontline training');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.card3.body', 'en', 'Sales order entry and AP/AR staff are usually the ones actually capturing the stricter master data these systems demand — training them on why a tax ID or classification code now matters more than it used to pays for itself quickly.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.card4.title', 'en', 'Ongoing data governance');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.card4.body', 'en', 'A one-time data cleanse before go-live degrades over time as new customers and vendors are added. A standing process for validating trading-partner master data keeps rejection rates low permanently, not just on day one.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.heading', 'en', 'Questions worth asking on day one');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.intro', 'en', 'A quick first-pass checklist for when a new mandate lands on your radar — before diving into technical specifications.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.q1', 'en', 'Which of our legal entities are actually in scope, and from what date — checked against group revenue thresholds where relevant, not just our own entity''s figures?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.q2', 'en', 'Which compliance model does this country use — post-audit, reporting, clearance, centralised platform, or Peppol-based — and what does that imply for our integration approach?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.q3', 'en', 'Can our current ERP produce the required format natively, or do we need a service provider / middleware layer?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.q4', 'en', 'Where does invoicing for this market currently happen — a shared service centre, a local team — and does that location raise any data residency questions?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.q5', 'en', 'What''s our current master data quality like for customers/vendors in this market — has anyone actually checked?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.q6', 'en', 'What happens operationally if an invoice is rejected — who''s notified, and how quickly can it be resolved before it affects a shipment or a payment?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.q7', 'en', 'Who owns this cross-functionally — is there one accountable person, or is this quietly five different people''s problem?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.q8', 'en', 'What''s the realistic cost at full production volume, not pilot volume?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.heading', 'en', 'Where to go next');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.card1.title', 'en', '📘 Understand the mandate types first');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.card1.body', 'en', 'If you haven''t already, "Types of Mandate" (also under Education) explains the compliance models referenced throughout this page in more depth.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.card2.title', 'en', '🗓️ Ready to start planning?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.card2.body', 'en', '"Preparing for a Mandate" (under Education) covers who to involve, when to start, and how to approach vendor selection.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.card3.title', 'en', '🌍 Check your specific country''s requirements');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.card3.body', 'en', 'The Deep Dives menu covers the exact technical specification, registration steps, and penalties for each of the 28 jurisdictions tracked here.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.card4.title', 'en', '✅ Find an accredited provider');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.card4.body', 'en', '"Government Certified Providers" (under Education) links directly to the official government registries for accredited service providers, country by country.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'footer.text', 'en', 'This page provides general educational context to help scope internal planning and is not legal, tax, or technical implementation advice. Specific requirements vary by country and by your own systems and group structure — consult the relevant country deep dive and a qualified advisor before making implementation decisions.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', '_meta.language', 'en', 'en');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', '_meta.reviewed', 'en', 'true');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'backLink', 'en', '← Back to global tracker');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'header.eyebrow', 'en', 'Education');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'header.title', 'en', 'Types of Mandate');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'header.sub', 'en', 'Every country''s e-invoicing rules boil down to a handful of underlying models. Once you recognise which one a country uses, its specific rules stop looking arbitrary.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'header.lastUpdated', 'en', 'Last updated:');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'stats.label1', 'en', 'Core models in use worldwide');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'stats.label2', 'en', 'Flavours of CTC');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'stats.label3', 'en', 'Countries mapped in this tracker');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.heading', 'en', 'The one question that explains everything');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.intro', 'en', 'Before comparing formats and deadlines, it helps to ask a single question about any country''s regime: <strong style="color:var(--text-lo);">does the tax authority see the invoice, and if so, before or after it reaches the buyer?</strong>');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card1.title', 'en', 'Never (or only on request)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card1.body', 'en', 'The tax authority doesn''t see individual invoices as a matter of course — it reviews records later, during an audit. This is the lightest-touch model.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card1.note', 'en', 'Examples: the United Kingdom, Canada, the United States (voluntary).');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card2.title', 'en', 'Afterwards, close to real time');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card2.body', 'en', 'The invoice reaches the buyer directly, but a copy or summary of the transaction data is reported to the tax authority shortly after — often within days, sometimes instantly.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card2.note', 'en', 'Examples: France''s e-reporting layer, Spain''s SII, Hungary''s RTIR.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card3.title', 'en', 'Before delivery — clearance');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card3.body', 'en', 'The invoice must be validated (and often digitally stamped) by the tax authority, or an accredited intermediary acting on its behalf, before it''s legally allowed to reach the buyer at all.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card3.note', 'en', 'Examples: Italy''s SDI, Poland''s KSeF, Mexico''s CFDI, Saudi Arabia''s ZATCA.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.heading', 'en', 'The seven models in practice');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.intro', 'en', 'In practice, these questions combine into seven recognisable architectures — most countries in this tracker are a clean fit for one of them.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card1.title', 'en', '1. Post-audit');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card1.body', 'en', 'Businesses exchange invoices freely, in whatever format they agree on. The tax authority reviews records after the fact, during an audit, rather than checking transactions as they happen.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card2.title', 'en', '2. Real-time reporting (CTC)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card2.body', 'en', 'Invoices are exchanged directly between businesses, but transaction data — sometimes the full invoice, sometimes a summary — is also reported to the tax authority in near-real time, alongside delivery rather than instead of it.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card3.title', 'en', '3. Clearance (CTC)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card3.body', 'en', 'The strictest model: an invoice has no legal effect until the tax authority (or its delegate) has validated it and returned a clearance reference. Only then can it be delivered to the buyer.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card4.title', 'en', '4. Centralised platform');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card4.body', 'en', 'A single government-run system handles both validation and delivery — buyer and seller both interact with the same central platform rather than routing through their own choice of provider.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card5.title', 'en', '5. Decentralised exchange — network mandated (Peppol)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card5.body', 'en', 'No government platform, but a specific network <em>is</em> prescribed by law. Businesses connect once to an accredited Access Point, and invoices route peer-to-peer using a common format — the "4-corner" model — because the mandate itself names Peppol as the required channel.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card6.title', 'en', '6. Format-only mandate — no prescribed channel');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card6.body', 'en', 'A genuinely lighter-touch pattern, easy to conflate with model 5 but meaningfully different: the law mandates a structured format, but doesn''t prescribe <em>how</em> the invoice has to be delivered — email, any network, any bilateral arrangement is fine, as long as the content is structured correctly. No clearance, no mandated reporting layer, no required network.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card6.note', 'en', 'Denmark is an even lighter variant again — its law mandates the <em>capability</em> to send/receive structured invoices, not that every invoice actually be exchanged that way.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card7.title', 'en', '7. Decentralised exchange + reporting (5-corner)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card7.body', 'en', 'Peppol''s 4-corner network with a fifth participant added: the tax authority, receiving transaction data automatically as a byproduct of normal exchange rather than a separate filing.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.heading', 'en', '"CTC" is a family, not one thing');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.intro', 'en', 'Continuous Transaction Controls (CTC) is an umbrella term covering models 2 and 3 above — both give the tax authority near-real-time visibility, but they differ on a point that matters enormously in practice: does the government see the invoice before or after it becomes legally valid?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.h1', 'en', 'Question');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.h2', 'en', 'CTC — Reporting');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.h3', 'en', 'CTC — Clearance');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r1k', 'en', 'Who sees the invoice first?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r1v1', 'en', 'The buyer — reporting happens alongside or shortly after');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r1v2', 'en', 'The tax authority — nothing is delivered until it clears');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r2k', 'en', 'Legal validity');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r2v1', 'en', 'The invoice is valid as issued; reporting is a parallel obligation');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r2v2', 'en', 'The invoice has no legal effect until cleared');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r3k', 'en', 'Failure mode');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r3v1', 'en', 'A late or missing report is a compliance breach, but the sale stands');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r3v2', 'en', 'A rejected invoice blocks the transaction — goods can''t legally ship');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r4k', 'en', 'Typical latency');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r4v1', 'en', 'Hours to a few days');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r4v2', 'en', 'Seconds to minutes');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r5k', 'en', 'Example');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r5v1', 'en', 'France''s e-reporting for B2C/cross-border sales');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r5v2', 'en', 'Italy''s SDI, Poland''s KSeF');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.heading', 'en', 'Where Peppol fits into all this');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.intro', 'en', 'Peppol is easy to misplace in this picture — it''s not a mandate model itself, it''s a piece of shared infrastructure that several different models are built on top of.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.card1.title', 'en', 'What Peppol actually is');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.card1.body', 'en', 'A standardised network and message format (Peppol BIS) that lets any two connected businesses exchange structured invoices without a bilateral integration — you connect once to an Access Point, not once per trading partner.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.card2.title', 'en', 'Pure infrastructure, not a policy');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.card2.body', 'en', 'Belgium and Australia both use Peppol, but only one of them requires it by law today. The network is the same; what a government chooses to bolt onto it (a mandate, a reporting requirement, nothing at all) is a separate decision.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.card3.title', 'en', 'The 4-corner → 5-corner evolution');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.card3.body', 'en', 'Add a fifth corner — the tax authority — and the same network starts feeding transaction data to government automatically. Singapore, the UAE, and Slovakia are all building toward this.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.flow1', 'en', 'Supplier');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.flow2', 'en', 'Supplier''s AP');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.flow3', 'en', 'Buyer''s AP');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.flow4', 'en', 'Buyer');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.heading', 'en', 'Where to go next');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.intro', 'en', 'This page is deliberately the "map" — for the fine detail on any one country, the country deep dives are where the specifics live.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.card1.title', 'en', '🌍 Check a specific country''s model');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.card1.body', 'en', 'Every deep dive in the "Deep Dives" menu states its compliance model up front, in the same terms used on this page — look for the "Compliance model" line under the country name.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.card2.title', 'en', '🏗️ See what this means for your business');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.card2.body', 'en', '"Impact of Mandate" (also under Education) covers the technical, process, financial, and organisational impact these models have in practice.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.card3.title', 'en', '📖 More education pages coming');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.card3.body', 'en', 'Deeper dives into CTC sub-types, a full map of Peppol-connected countries, and an overview of service providers operating in this space are all planned additions to this menu.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.card4.title', 'en', '🔔 Get notified when they land');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.card4.body', 'en', 'Subscribers get priority access to new education content as it''s published, alongside the monthly compliance digest itself.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'footer.text', 'en', 'This page provides general educational context and is not legal or tax advice. Compliance models can and do evolve — a country''s own deep dive is the authoritative source for its current specific requirements.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', '_meta.language', 'en', 'en');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', '_meta.reviewed', 'en', 'true');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'backLink', 'en', '← Back to global tracker');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'header.eyebrow', 'en', 'Education');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'header.title', 'en', 'Preparing for a Mandate');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'header.sub', 'en', 'Once you understand the mandate model and its likely impact, the practical questions become: who should be in the room, how early should this start, and how do you approach choosing a vendor without regretting it a year later?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'header.lastUpdated', 'en', 'Last updated:');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'stats.label1', 'en', 'Recommended lead time before go-live');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'stats.label2', 'en', 'Typical core working group size');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'stats.label3', 'en', 'Of a well-run vendor selection');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.heading', 'en', 'Who to include');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.intro', 'en', 'A mandate response with no single accountable owner, or with the wrong functions missing from the room, is the most common cause of late surprises. Here''s a working group that covers the ground without becoming unwieldy.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card1.title', 'en', 'Programme sponsor');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card1.body', 'en', 'A senior Finance or Tax leader with the authority to commit budget and resolve cross-functional disagreements. Without this, the working group can identify problems but not always act on them quickly.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card2.title', 'en', 'Tax / compliance lead');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card2.body', 'en', 'Owns the interpretation of the actual legal requirement, tracks scope and deadlines across entities, and is usually the one relationship-managing any external advisors.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card3.title', 'en', 'IT / integration lead');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card3.body', 'en', 'Assesses what the current ERP/AP/AR systems can and can''t do natively, and owns the technical relationship with whichever vendor or platform gets selected.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card4.title', 'en', 'Legal &amp; data protection');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card4.body', 'en', 'Reviews vendor contracts, data residency implications, and cross-border transfer questions — brought in from the start rather than at contract-signing, when it''s too late to influence the shape of the deal.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card5.title', 'en', 'Business/entity owner(s)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card5.body', 'en', 'Someone accountable for each affected country or business unit — particularly important in multinationals, where the same mandate can land differently depending on local entity structure and existing systems.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card6.title', 'en', 'Procurement / vendor management');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card6.body', 'en', 'Runs the formal RFP process if one is needed, and ensures contract terms (SLAs, exit clauses, liability) get proper commercial scrutiny rather than being accepted as vendor boilerplate.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.outro', 'en', 'Keep this group to 6–8 people who meet regularly, with a wider circle (AP/AR team leads, key customers or vendors for testing, external advisors) consulted at specific milestones rather than in every meeting.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.heading', 'en', 'When to start');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.intro', 'en', 'Grace periods and phased thresholds are common, and it''s tempting to treat them as the real deadline. In practice, vendor lead times, testing cycles, and cross-functional coordination all take longer than expected — starting early is what actually determines whether go-live is calm or chaotic.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.marker1', 'en', '12–18 months before go-live');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.marker2', 'en', '9–12 months before go-live');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.marker3', 'en', '6–9 months before go-live');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.marker4', 'en', '3–6 months before go-live');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.marker5', 'en', '1–3 months before go-live');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.marker6', 'en', 'Go-live and beyond');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card1.date', 'en', 'Assessment &amp; scoping');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card1.badge', 'en', 'Start here');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card1.title', 'en', 'Confirm scope, form the working group, assess current systems');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card1.desc', 'en', 'Determine which entities are actually in scope and from when, form the core working group above, and get an honest read on what your current ERP/AP/AR systems can and can''t do without help.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card2.date', 'en', 'Vendor selection &amp; solution design');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card2.title', 'en', 'Run the vendor selection process (see below) and confirm the technical approach');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card2.desc', 'en', 'This is usually the single most time-consuming phase — treat it as its own project with its own timeline, not a quick procurement exercise.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card3.date', 'en', 'Build &amp; integration');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card3.title', 'en', 'Technical integration, master data cleansing, internal process design');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card3.desc', 'en', 'Master data cleansing in particular benefits from a long runway — it''s rarely a quick fix once you actually look at the state of customer/vendor records.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card4.date', 'en', 'Testing &amp; pilot');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card4.title', 'en', 'Sandbox/certification testing, then a live pilot with a small transaction subset');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card4.desc', 'en', 'Deliberately test failure paths — rejections, corrections, offline/contingency modes — not just the happy path where everything validates first time.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card5.date', 'en', 'Parallel run &amp; cutover prep');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card5.title', 'en', 'Run old and new processes in parallel, train frontline staff, finalise contingency plans');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card5.desc', 'en', 'This is also when to brief customers and key vendors on what''s changing, if the mandate affects how they''ll receive or send invoices to you.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card6.date', 'en', 'Stabilisation');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card6.title', 'en', 'Monitor rejection rates closely for the first few weeks');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card6.desc', 'en', 'Rejection rates typically spike immediately after go-live as real-world data edge cases surface that testing didn''t catch — budget attention for this rather than assuming go-live is the finish line.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.heading', 'en', 'Planning a vendor selection process');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.intro', 'en', 'Whether you need a full-service compliance platform, a specific country intermediary (a PAC, OSE, or Access Point), or just a module within your existing ERP, the same disciplined process pays off.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step1.title', 'en', 'Define requirements before talking to any vendor');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step1.body', 'en', 'Country/format coverage needed, expected transaction volume, required integration method (API vs. portal), and budget range. Going to market without this tends to produce proposals that are hard to compare fairly.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step2.title', 'en', 'Map the realistic vendor landscape');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step2.body', 'en', 'Options usually span full-service global compliance platforms, country-specific intermediaries, and native ERP add-on modules — each with different trade-offs on coverage breadth versus depth and cost.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step3.title', 'en', 'Score on more than price');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step3.body', 'en', 'Format/country coverage, uptime and support SLAs (including support hours relative to your time zone), security certifications, integration effort required on your side, and — critically — their track record of keeping pace with regulatory changes in the countries you need.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step4.title', 'en', 'Insist on a proof of concept');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step4.body', 'en', 'A sandbox test with your own real (or realistic) data surfaces integration friction that a sales demo never will. Treat this as non-negotiable before signing, not an optional nice-to-have.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step5.title', 'en', 'Scrutinise the contract, not just the product');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step5.body', 'en', 'Data residency commitments, liability for errors or missed deadlines, minimum continuity periods if you switch providers, and clear exit/data-portability terms — get Legal and Procurement involved in this stage directly, not as a final rubber stamp.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step6.title', 'en', 'Plan for the next mandate, not just this one');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step6.body', 'en', 'If you operate in multiple markets, ask how the vendor''s roadmap covers countries you don''t need yet but might soon — switching providers again in two years is a real cost worth avoiding if a single relationship can reasonably grow with you.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.heading', 'en', 'Common pitfalls');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.intro', 'en', 'Patterns worth watching for, based on how these programmes typically go wrong.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card1.title', 'en', '⏳ Treating the grace period as the real deadline');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card1.body', 'en', 'Enforcement holidays exist to ease the transition, not to signal there''s no urgency — the underlying technical and process work still needs to happen on the original timeline.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card2.title', 'en', '🗂️ Skipping master data cleansing');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card2.body', 'en', 'The single most common cause of early rejections, and the easiest thing to deprioritise under time pressure — it rarely pays off to skip it.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card3.title', 'en', '🙋 No single accountable owner');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card3.body', 'en', 'When Finance, IT, and Legal each think someone else is driving, gaps surface late — usually right when there''s no time left to fix them.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card4.title', 'en', '🧪 Only testing the happy path');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card4.body', 'en', 'Rejections, corrections, and contingency/offline modes are exactly where real operational pain shows up — test these deliberately, not just the case where everything works first time.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card5.title', 'en', '🌍 Assuming one market''s solution transfers to the next');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card5.body', 'en', 'A vendor or approach that works well in one country''s model doesn''t automatically fit another''s — re-verify fit market by market rather than assuming.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card6.title', 'en', '💸 Comparing vendors on pilot-volume pricing');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card6.body', 'en', 'Cost structures that look similar at low volume can diverge sharply at real production volume — always model pricing at your actual expected scale.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.heading', 'en', 'Quick-start checklist');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q1', 'en', 'Named programme sponsor with budget authority, confirmed');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q2', 'en', 'Core working group formed — Tax, IT, Legal, Procurement, and affected business units represented');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q3', 'en', 'Scope confirmed: which entities, from when, under which compliance model');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q4', 'en', 'Current system capability assessed honestly, gaps documented');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q5', 'en', 'Vendor requirements documented before any vendor conversations begin');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q6', 'en', 'Proof-of-concept testing scheduled before contract sign-off, not after');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q7', 'en', 'Master data cleansing plan in motion, not deferred to "later"');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q8', 'en', 'Rejection and correction workflows explicitly tested, not assumed');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q9', 'en', 'Frontline (AP/AR, sales order entry) training scheduled ahead of go-live');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.heading', 'en', 'Where to go next');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card1.title', 'en', '📘 Not sure which model applies?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card1.body', 'en', '"Types of Mandate" (under Education) explains the compliance models referenced throughout this page.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card2.title', 'en', '🏗️ Understand the full impact first');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card2.body', 'en', '"Impact of Mandate" goes deeper on the technical, process, and financial effects this planning work is ultimately responding to.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card3.title', 'en', '🌍 Check your specific country''s requirements');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card3.body', 'en', 'The Deep Dives menu covers the exact technical specification, registration steps, and penalties for each of the 28 jurisdictions tracked here.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card4.title', 'en', '🏷️ Understand the vendor landscape first');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card4.body', 'en', '"Types of Provider" (under Education) breaks down the five categories of vendor referenced in the selection process above — ERP, Solution Provider, Tax Compliance, Technology, and Consultancy.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card5.title', 'en', '✅ Find an accredited provider');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card5.body', 'en', '"Government Certified Providers" (under Education) links directly to the official registries referenced in the vendor selection section above.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'footer.text', 'en', 'This page provides general educational guidance based on common patterns in mandate readiness programmes, and is not legal, tax, or procurement advice. Specific timelines and requirements vary by country and by your own systems and organisation — consult the relevant country deep dive and appropriate advisors before committing to a plan.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', '_meta.language', 'en', 'en');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', '_meta.reviewed', 'en', 'true');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'backLink', 'en', '← Back to global tracker');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'header.eyebrow', 'en', 'Education');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'header.title', 'en', 'Types of Provider');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'header.sub', 'en', '"Get a vendor" undersells how varied this market actually is. Five genuinely different categories of provider all sell into e-invoicing compliance — understanding which one you''re talking to changes what you should expect from them.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'header.lastUpdated', 'en', 'Last updated:');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'statusBanner.text', 'en', 'Company names below are <strong>illustrative examples only</strong> — a small, non-exhaustive sample to make each category concrete, not a recommendation or ranking. Many real providers straddle more than one category.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'stats.label1', 'en', 'Distinct provider categories');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'stats.label2', 'en', 'Categories most programmes actually combine');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'stats.label3', 'en', 'Category that covers everything alone');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec1.heading', 'en', 'Why the category matters before the name does');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec1.intro', 'en', 'Two providers can both say "we do e-invoicing" and mean genuinely different things by it. Knowing which category you''re evaluating tells you what questions to actually ask — and what gaps to expect and plan around.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.heading', 'en', 'The five categories');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.strengthsLabel', 'en', 'Typical strengths');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.tradeoffsLabel', 'en', 'Typical trade-offs');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.examplesLabel', 'en', 'Illustrative examples:');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card1.title', 'en', '1. ERP Providers');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card1.what', 'en', 'Full enterprise resource planning suites — finance, supply chain, HR, and more — that have built e-invoicing compliance as a native or add-on module within their own platform.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card1.s1', 'en', 'Native to your core system of record — no separate data extraction layer');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card1.s2', 'en', 'Single vendor relationship if you''re already a customer');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card1.s3', 'en', 'Consistent master data, since it never leaves the ERP');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card1.t1', 'en', 'Country coverage and update speed can lag specialist providers, especially for newer or smaller markets');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card1.t2', 'en', 'Often still needs a bolt-on module or partner for full global reach');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card1.t3', 'en', 'Less flexible if you run more than one ERP across your group');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card2.title', 'en', '2. Solution Providers (AP/AR specialists)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card2.what', 'en', 'Providers focused specifically on accounts payable and accounts receivable automation, e-invoice exchange, and acting as the accredited intermediary (Access Point, PAC, OSE) a given country''s mandate requires.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card2.s1', 'en', 'Deep, often faster-moving country and format coverage — this is their whole business');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card2.s2', 'en', 'ERP-agnostic — designed to plug into whatever system(s) you already run');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card2.s3', 'en', 'Purpose-built for the exchange and validation layer specifically');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card2.t1', 'en', 'Another vendor relationship and contract to manage alongside your ERP');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card2.t2', 'en', 'Integration effort still required to connect it to your core systems');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card3.title', 'en', '3. Tax Compliance Providers');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card3.what', 'en', 'Providers whose core business is broader indirect tax compliance — VAT/GST determination, returns, and reporting — who have extended into e-invoicing as part of that wider tax technology stack.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card3.s1', 'en', 'One provider for both tax determination and e-invoicing, if you already use them for tax');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card3.s2', 'en', 'Deep tax-technical expertise underpinning the compliance logic');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card3.t1', 'en', 'E-invoicing may be a newer part of their offering than their core tax product — check country coverage maturity specifically for this, not just their tax reputation generally');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card4.title', 'en', '4. Technology Providers (EDI / middleware)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card4.what', 'en', 'Providers whose core competency is broader B2B data exchange and integration middleware — often long-established in EDI — who have added structured e-invoice format support as an extension of that existing capability.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card4.s1', 'en', 'If you already run significant EDI trading-partner volume, extends the same integration layer rather than adding a parallel system');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card4.s2', 'en', 'Strong general-purpose data mapping and transformation capability');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card4.t1', 'en', 'CTC-specific nuances — real-time clearance, digital signatures, government reporting — are often a newer layer on top of EDI-first architecture rather than core DNA');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card5.title', 'en', '5. Consultancies');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card5.what', 'en', 'Advisory and implementation firms — not a software product themselves — offering assessment, vendor selection support, and programme management for a mandate response.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card5.s1', 'en', 'Independent of any one software vendor, which can mean more objective vendor selection support');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card5.s2', 'en', 'Useful for complex, multi-country, multi-entity programmes needing dedicated programme management');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card5.t1', 'en', 'Doesn''t replace the need for an actual software/service provider — this is a complementary layer');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card5.t2', 'en', 'Typically time-and-materials cost rather than a predictable per-transaction fee');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.heading', 'en', 'Side by side');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.intro', 'en', 'A rough guide to how the categories typically differ — real providers vary, and several deliberately straddle more than one row.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.h1', 'en', 'Category');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.h2', 'en', 'Core business');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.h3', 'en', 'Country coverage depth');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.h4', 'en', 'Typical cost model');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r1c1', 'en', 'ERP Provider');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r1c2', 'en', 'Full business system, e-invoicing as a module');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r1c3', 'en', 'Varies — strong in home markets, can lag elsewhere');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r1c4', 'en', 'Licensing + module fees');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r2c1', 'en', 'Solution Provider');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r2c2', 'en', 'AP/AR automation &amp; e-invoice exchange');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r2c3', 'en', 'Usually broad — this is their specialism');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r2c4', 'en', 'Per-transaction or subscription');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r3c1', 'en', 'Tax Compliance Provider');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r3c2', 'en', 'Indirect tax determination &amp; filing');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r3c3', 'en', 'Strong where their tax product is established');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r3c4', 'en', 'Subscription, often bundled with tax');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r4c1', 'en', 'Technology Provider');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r4c2', 'en', 'B2B data exchange / EDI middleware');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r4c3', 'en', 'Strong where EDI trading is already established');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r4c4', 'en', 'Per-transaction or platform fee');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r5c1', 'en', 'Consultancy');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r5c2', 'en', 'Advisory &amp; implementation services');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r5c3', 'en', 'Advisory reach, not a technical platform itself');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r5c4', 'en', 'Time-and-materials or fixed-fee project');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec4.heading', 'en', 'How these actually combine in practice');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec4.intro', 'en', 'Very few real mandate programmes use just one category — most combine two or three, each covering a different part of the problem.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec4.scenarioTitle', 'en', 'A realistic multinational scenario');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec4.scenarioBody', 'en', 'A group running SAP globally uses its ERP''s native compliance module for markets where coverage is mature, brings in a specialist Solution Provider specifically to cover a handful of countries the ERP module doesn''t yet support well, and engages a consultancy for a few months to run programme management across the whole rollout and support vendor selection.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec4.flow1', 'en', 'ERP module — mature markets');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec4.flow2', 'en', 'Solution Provider — coverage gaps');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec4.flow3', 'en', 'Consultancy — programme oversight');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec5.heading', 'en', 'Questions worth asking, whichever category you''re evaluating');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec5.q1', 'en', 'Is e-invoicing genuinely core to this provider''s business, or a bolt-on to something else they sell?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec5.q2', 'en', 'How quickly have they historically added support for newly announced mandates?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec5.q3', 'en', 'Do they hold accreditation directly, or do they rely on a third party underneath them for certain countries?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec5.q4', 'en', 'If they''re a specialist in one category, who do they expect you to bring in to cover the others?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec5.q5', 'en', 'What does their roadmap look like for countries you don''t need yet, but might in a year or two?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec6.heading', 'en', 'Further reading: analyst research');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec6.intro', 'en', 'Five research firms actively cover this market and are worth knowing about if you want independent validation beyond any single vendor''s own claims. Most full reports sit behind a subscription or a vendor-provided excerpt, but each firm below also publishes something genuinely accessible without one.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec6.gartner', 'en', 'Publishes an annual Magic Quadrant for Accounts Payable Applications, alongside a dedicated "E-invoicing Compliance Applications" category on Gartner Peer Insights — real, browsable user reviews, no subscription required.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec6.forrester', 'en', 'Publishes The Forrester Wave™: Accounts Payable Invoice Automation Software periodically (most recently Q2 2026). The full Wave requires Forrester access, but their own blog announcement summarising each edition''s findings is publicly readable.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec6.idc', 'en', 'Publishes IDC MarketScape vendor assessments covering e-invoicing and VAT compliance software, both worldwide and Europe-specific editions. The full assessments are paywalled, but IDC''s own blog series on e-invoicing is a genuinely useful, freely accessible starting point.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec6.spendMatters', 'en', 'Runs SolutionMap, a rankings system covering procurement technology across 16 source-to-pay categories including AP automation. Worth knowing: Spend Matters is now a division of The Hackett Group following a merger, so the two are increasingly one research organisation rather than fully independent of each other.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec6.hackett', 'en', 'Runs large-scale benchmarking studies across procure-to-pay and accounts payable performance, including specific research on how AI is changing AP solutions and global e-invoicing/CTC compliance capability.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec6.footnote', 'en', 'Specific named editions (e.g., "Q2 2026") get superseded on a regular cycle — check each firm''s own site for the current version rather than assuming any specific edition referenced here, or anywhere else, is still the latest by the time you read this.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec7.heading', 'en', 'Where to go next');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec7.card1.title', 'en', '🗓️ Run the actual selection process');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec7.card1.body', 'en', '"Preparing for a Mandate" (under Education) covers how to define requirements, run a proof of concept, and scrutinise a contract once you know which category fits.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec7.card2.title', 'en', '✅ Check government-verified providers');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec7.card2.body', 'en', '"Government Certified Providers" links directly to official registries where several countries publish accredited providers by name.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec7.card3.title', 'en', '🌍 Check your specific country''s requirements');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec7.card3.body', 'en', 'The Deep Dives menu covers exact technical specifications and registration steps for each of the 28 jurisdictions tracked here.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'footer.text', 'en', 'Company names in this page are illustrative examples only, included to make each category concrete — they are not endorsements, rankings, or a complete market map, and their inclusion does not imply any relationship with this site. Analyst research referenced above is linked for general awareness only; full reports may require a paid subscription or vendor-provided access, and any vendor positioning within them reflects that firm''s own methodology and views, not ours. Verify any specific provider''s current accreditation and fit for your needs directly before engaging them.');
