INSERT INTO translations (namespace, key, lang, value) VALUES ('feedback', 'form.submitButton', 'en', 'Send feedback');
INSERT INTO translations (namespace, key, lang, value) VALUES ('feedback', 'form.fineprint', 'en', 'This page runs entirely in your browser — connect the form to a real inbox, helpdesk, or webhook to go live.');
