INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', '_meta.language', 'en', 'en');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', '_meta.reviewed', 'en', 'true');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'backLink', 'en', '← Back to global tracker');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.eyebrow', 'en', 'Never get caught off guard');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.title', 'en', 'Get notified the moment a government changes the rules');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.intro', 'en', 'E-invoicing thresholds, wave numbers, and go-live dates change constantly — often with little public notice. Subscribe once, and every government update or announcement across the 28 jurisdictions we track lands in your inbox automatically, in plain language, before it catches your team off guard.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.sampleLink', 'en', '👀 See a real sample issue (January 2026) →');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.stat1', 'en', 'Jurisdictions tracked');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.stat2', 'en', 'Digest cadence');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.stat3', 'en', 'Spam between issues');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item1.title', 'en', 'Real government announcements, summarised');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item1.body', 'en', 'Every new mandate, shifted deadline, and penalty change we track, written in plain language — not legal text copy-pasted from a tax authority''s press release.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item2.title', 'en', 'Choose exactly which countries you care about');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item2.body', 'en', 'Tell us which of the 28 jurisdictions matter to your business, and your monthly notification email tells you specifically whether they came up — or get the full global digest if you''d rather see everything.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item3.title', 'en', 'A full, searchable back-catalogue');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item3.body', 'en', 'Every past issue lives in a searchable, filterable archive — look back at any month, any country, any time, not just whatever landed in your inbox most recently.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item4.title', 'en', 'Priority access to new education content');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item4.body', 'en', 'New country deep dives and education guides get flagged to subscribers first, as we publish them.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.eyebrow', 'en', 'Subscribe');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.title', 'en', 'Get started');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.sub', 'en', 'One email a month, plus a short alert whenever a new issue covering your countries goes live. You''ll choose recurring or one-time payment on the next, secure step.');
