INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.form.emailError', 'en', 'A valid email address is required');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.form.jobTitle', 'en', 'Title');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.form.jobTitleError', 'en', 'Title is required');
