INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.countriesLabel', 'en', 'Which countries do you want alerts for?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.countriesHint', 'en', 'Optional — leave everything unchecked and we''ll send the full monthly digest covering all 28 jurisdictions.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.countriesMissing', 'en', 'Country selection is temporarily unavailable — you''ll still get the full monthly digest. (Missing file: countries.js)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.selectAll', 'en', 'Select all');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.clearAll', 'en', 'Clear all');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.submitButton', 'en', 'Continue to secure payment');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.fineprint', 'en', 'Payment is handled by Lemon Squeezy, our merchant of record — they collect and remit any applicable VAT/GST on this sale, so you''re never charged tax separately. We never see or store your card details. See our <a href="privacy-policy.html" style="color:#b5432f; text-decoration:underline;">privacy policy</a> for how your data is handled.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'confirm.eyebrow', 'en', 'One more step');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'confirm.title', 'en', 'Confirm your details');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'confirm.subscribingAs', 'en', 'Subscribing as');
