INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'confirm.alertsFor', 'en', 'Alerts for:');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'confirm.fullDigest', 'en', 'the full digest (all 28 jurisdictions)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'confirm.fineprint', 'en', 'You''ll be taken to a secure Lemon Squeezy checkout window, where you can choose recurring or one-time payment and complete your purchase.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'confirm.payButton', 'en', 'Continue to checkout →');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'confirm.editLink', 'en', '← Edit my details');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'modal.close', 'en', '✕ Close');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'modal.badge', 'en', 'Real sample issue — not a mockup');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'modal.fineprint', 'en', 'This is the actual first issue sent to subscribers, exactly as published — nothing edited or shortened for this preview. Every subscriber gets access to the full searchable archive, not just this one issue.');
