INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'brand.eyebrow', 'en', 'Compliance clearance board');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'brand.title', 'en', 'The E-Invoicing<br>Compliance Corner');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'brand.description', 'en', 'A living tracker of e-invoicing and digital reporting mandates across 28 countries — EU-wide ViDA rules, national CTC systems, and everything in between. Each entry shows the deadline, what you need to do about it, and a direct link to the official government portal, so you can go from "is this relevant to us?" to "here''s what to action" in one page.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'perks.heading', 'en', 'Subscribers also get');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'perks.item1', 'en', 'A monthly email digest — every new mandate or deadline change, summarised');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'perks.item2', 'en', 'Full access to the newsletter archive, not just this month''s issue');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'perks.item3', 'en', 'Priority access to new country deep dives as they''re published');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'perks.item4', 'en', 'Plain-language "what this means for your team" write-ups, not just legal text');
