INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.label', 'en', 'Getting around this site');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip1Title', 'en', 'Filter to what matters to you');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip1Desc', 'en', 'Use the region and status pills, or the search box, to narrow the timeline down to your markets.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip2Title', 'en', 'Go deep on a country');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip2Desc', 'en', 'The "Deep Dives" menu links to a full technical breakdown — file formats, transmission protocols, registration steps, and penalties.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip3Title', 'en', 'Jump straight to a portal');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip3Desc', 'en', 'The sidebar (☰ on mobile) links directly to the official government portal for every country tracked here.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip4Title', 'en', 'Old news is tucked away');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip4Desc', 'en', 'The timeline shows recent and upcoming changes by default — long-settled regulations live in the collapsed section below it.');
