INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'about.eyebrow', 'en', 'About');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'about.title', 'en', 'The E-Invoicing Compliance Corner');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'about.p1', 'en', 'The E-Invoicing Compliance Corner was created in response to the growing complexity and rapid spread of e-invoicing mandates worldwide. Whether you''re a small business or a global enterprise, this can be a difficult and costly subject to navigate.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'about.p2', 'en', 'This site aims to provide a low-cost, easy way to access accurate information quickly — and to give you ongoing alerts whenever mandates change or new legislation is introduced.');
