INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'filters.disclaimer', 'en', 'This tracker reflects publicly available guidance as of July 2026 and is provided for general awareness, not legal or tax advice. E-invoicing thresholds, wave numbers and go-live dates change frequently — confirm your obligations directly on the official government portal linked in each entry, or with your tax advisor, before making compliance decisions.');
