INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'filters.recentIntro', 'en', 'Milestones from the last few months through the furthest confirmed deadline. Already-settled regulations live in the collapsed section below so this list stays focused on what''s actually changing.');
