INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', '_meta.language', 'es', 'es');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', '_meta.reviewed', 'es', 'true');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'backLink', 'es', '← Volver al panel general');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'header.eyebrow', 'es', 'Educación');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'header.title', 'es', 'Proveedores certificados por el gobierno');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'header.sub', 'es', 'Dónde encontrar la lista oficial, publicada por el gobierno, de proveedores de servicios acreditados o software listo para Peppol de cada país — verificada directamente en el propio sitio de la autoridad correspondiente, no en un resumen de terceros.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'header.lastUpdated', 'es', 'Última actualización:');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'statusBanner.text', 'es', 'Este es un <strong>conjunto inicial de enlaces verificados</strong>, no un mapa completo de las 28 jurisdicciones seguidas. Cada enlace de abajo se comprobó directamente en el propio sitio web del gobierno/autoridad mencionado. Varios países de este seguimiento simplemente no gestionan un registro público de acreditación — vea la nota de la Sección 3 antes de asumir que existe uno.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'stats.label1', 'es', 'Países verificados hasta ahora');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'stats.label2', 'es', 'Términos de acreditación distintos en uso');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'stats.label3', 'es', 'Directorio global de proveedores Peppol');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec1.heading', 'es', 'Misma idea, nombres distintos');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec1.intro', 'es', 'Cada país de abajo gestiona una versión del mismo concepto — una lista reconocida por el gobierno de software o intermediarios en los que puede confiar de forma segura — pero cada uno usa su propio término para ello.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec1.card1.body', 'es', 'Se usa en los EAU. El intermediario que valida y transmite sus facturas electrónicas a través de la red Peppol en su nombre.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec1.card2.body', 'es', 'Se usa en México. El tercero autorizado por el SAT para sellar (timbrar) su CFDI y darle validez legal.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec1.card3.body', 'es', 'Se usa en Perú. Un OSE valida su factura con la misma autoridad legal que la propia SUNAT; un PSE firma en su nombre usando su propio certificado.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec1.card4.body', 'es', 'Se usa en India. Un intermediario con licencia que proporciona la capa de software/API que conecta a un contribuyente con la GSTN.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec1.card5.title', 'es', 'Proveedor de Servicios Peppol / Punto de Acceso');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec1.card5.body', 'es', 'Se usa en Malasia, Singapur, Australia y cualquier otro mercado basado en Peppol. Un Punto de Acceso acreditado conecta su empresa a la red Peppol compartida.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.heading', 'es', 'Enlaces oficiales verificados, por país');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.intro', 'es', 'Vaya directamente a la página propia de la autoridad — verifique siempre allí el estado actual de un proveedor concreto antes de firmar nada, ya que estas listas cambian.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.h1', 'es', 'País');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.h2', 'es', 'Qué se lista');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.h3', 'es', 'Fuente oficial');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.uae', 'es', 'Registro del Ministerio de Finanzas de Proveedores de Servicios de facturación electrónica preaprobados/acreditados (ASP)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.mexico', 'es', 'Registro del SAT de Proveedores Autorizados de Certificación');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.peru', 'es', 'Padrón oficial de la SUNAT (registro) de proveedores OSE y PSE autorizados');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.india', 'es', 'Lista de la GSTN de Proveedores de GST Suvidha con licencia');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.malaysia', 'es', 'Registro de la MDEC (Autoridad Peppol de Malasia) de Proveedores de Servicios Peppol acreditados');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.singapore', 'es', 'Lista de la IMDA de proveedores de Punto de Acceso autorizados y soluciones listas para InvoiceNow');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.australia', 'es', 'Registro de la ATO (Autoridad Peppol de Australia) de proveedores de servicios Peppol acreditados');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.table.france', 'es', 'Lista de la DGFiP de Plateformes Agréées registradas (antes PDP)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec2.franceNote', 'es', 'La lista exacta de Francia se encuentra dentro del sitio más amplio impots.gouv.fr de la DGFiP, en lugar de en una URL fija y estable que podamos verificar con plena confianza — busque "liste des plateformes agréées" directamente en ese sitio para la versión actual.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec3.heading', 'es', 'Dónde no se aplica este patrón');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec3.intro', 'es', 'Varios mercados importantes de este seguimiento simplemente no gestionan ningún registro público de acreditación de proveedores — vale la pena saberlo para no buscar uno que no existe.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec3.card1.body', 'es', 'KSeF y SDI son ambos plataformas gubernamentales directas — cualquier software conforme puede conectarse mediante la API/esquema publicados, sin ninguna capa formal de "intermediario acreditado" frente a la que certificarse.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec3.card2.body', 'es', 'Los contribuyentes se autocertifican como emisores autorizados directamente ante la autoridad fiscal (SEFAZ, SII); no existe un modelo equivalente de acreditación de terceros al estilo PAC/OSE en ninguno de los dos países.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec3.card3.body', 'es', 'ZATCA no publica una lista pública comparable — el cumplimiento consiste en que su sistema de facturación cumpla directamente la especificación técnica publicada, no en la acreditación de intermediarios.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec4.heading', 'es', 'Un recurso que abarca todos los mercados Peppol');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec4.body', 'es', 'Para cualquier país basado en Peppol que aún no esté en la tabla anterior — Bélgica, Noruega, Dinamarca y otros — el propio OpenPeppol (el organismo rector de la red) mantiene un único registro global de todos los proveedores de servicios Peppol certificados, consultable por país de residencia legal.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.heading', 'es', 'A dónde ir después');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.card1.title', 'es', '🏷️ Entienda primero las categorías de proveedor');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.card1.body', 'es', '"Tipos de proveedor" (en Educación) desglosa las categorías de ERP, Proveedor de Solución, Cumplimiento Fiscal, Tecnología y Consultoría antes de que empiece a consultar las listas gubernamentales.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.card2.title', 'es', '🗓️ ¿Listo para ejecutar una selección de proveedor?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.card2.body', 'es', '"Preparación para un mandato" (en Educación) explica cómo evaluar y seleccionar un proveedor una vez que ha encontrado la lista correcta.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.card3.title', 'es', '🌍 Consulte los requisitos específicos de su país');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.card3.body', 'es', 'El menú de análisis por país cubre los pasos exactos de registro, las especificaciones técnicas y las sanciones de cada una de las 28 jurisdicciones seguidas aquí.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.card4.title', 'es', '📬 Esta lista crecerá');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'sec5.card4.body', 'es', 'Se añadirán más países aquí a medida que verifiquemos directamente sus fuentes oficiales — los suscriptores reciben una notificación cuando se publican nuevas entradas.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-certified-providers', 'footer.text', 'es', 'Esta página enlaza directamente con fuentes oficiales de gobiernos y autoridades verificadas en la fecha indicada arriba, y se ofrece con fines informativos generales — no constituye un aval de ningún proveedor concreto, y la inclusión en una lista gubernamental no garantiza su idoneidad para sus necesidades específicas. Confirme siempre el estado de acreditación actual de un proveedor directamente en la página oficial enlazada antes de firmar cualquier acuerdo.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', '_meta.language', 'es', 'es');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', '_meta.reviewed', 'es', 'true');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'backLink', 'es', '← Volver al panel general');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'header.eyebrow', 'es', 'Educación');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'header.title', 'es', 'Impacto del mandato');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'header.sub', 'es', 'Un nuevo mandato de facturación electrónica rara vez se queda solo en TI. Esta página recorre dónde aterriza realmente el impacto en una empresa — técnico, de procesos, financiero y organizativo — para que pueda dimensionar el proyecto real, no solo la compra de software.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'header.lastUpdated', 'es', 'Última actualización:');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'stats.label1', 'es', 'Funciones habitualmente implicadas');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'stats.label2', 'es', 'Algunas ventanas de emisión, antes en días');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'stats.label3', 'es', 'Una factura rechazada puede bloquear un envío');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.heading', 'es', 'Por qué esto es más que un proyecto de TI');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.intro', 'es', 'El error más común al dimensionar la respuesta a un mandato es tratarlo como "conectar nuestro ERP a un nuevo formato". En la práctica, la mayoría de los mandatos afectan al menos a cinco funciones simultáneamente — y cada una descubre su parte del trabajo en un momento distinto, normalmente demasiado tarde.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.card1.title', 'es', 'Finanzas y Fiscalidad');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.card1.body', 'es', 'Es responsable de la propia obligación de cumplimiento, y normalmente de la relación con la plataforma o intermediario elegido — pero a menudo carece de visibilidad sobre si el ERP puede realmente producir lo requerido.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.card2.title', 'es', 'TI');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.card2.body', 'es', 'Construye la integración, pero con frecuencia se incorpora solo cuando Finanzas ya se ha comprometido con una fecha límite — dejando poco margen para influir en el alcance o el calendario.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.card3.title', 'es', 'Legal y Protección de Datos');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.card3.body', 'es', 'Necesita opinar sobre la residencia de datos, la transferencia transfronteriza y los términos contractuales con nuevos intermediarios — a menudo la última función consultada, cuando debería ser una de las primeras.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.card4.title', 'es', 'Ventas, Compras y Logística');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec1.card4.body', 'es', 'Capturan los datos maestros (identificadores fiscales, códigos de clasificación, direcciones) que los sistemas de compensación ahora validan estrictamente — y son quienes lo sienten operativamente cuando un envío queda bloqueado por una factura rechazada.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.heading', 'es', 'Impacto técnico');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.intro', 'es', 'Aquí es normalmente donde comienza la planificación — y donde la complejidad real es más fácil de subestimar, especialmente cuando hay más de una jurisdicción implicada.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card1.title', 'es', 'Enfoque de integración');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card1.body', 'es', 'Integración directa vía API ERP-plataforma, una capa de middleware/proveedor de servicios (PAC, OSE, Punto de Acceso), o un recurso manual vía portal web para volúmenes bajos — cada uno tiene un perfil distinto de coste, velocidad y mantenimiento.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card1.note', 'es', 'La opción de "portal manual" a menudo parece gratuita a bajo volumen, y luego se convierte en el cuello de botella en cuanto el volumen crece — modele ambos escenarios.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card2.title', 'es', 'Fragmentación de formatos');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card2.body', 'es', 'No existe un formato universal de factura electrónica. UBL, CII, JSON y esquemas específicos de cada país (CFDI, FA(3), e-fapiao) coexisten — una empresa que opera en varios mercados con mandato está, en la práctica, manteniendo varias integraciones técnicas distintas, no una sola.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card3.title', 'es', 'Calidad de los datos maestros');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card3.body', 'es', 'Los sistemas de compensación validan en tiempo real los identificadores fiscales, códigos de clasificación de producto/servicio y datos del comprador. Datos que eran "suficientemente buenos" para un campo interno del ERP a menudo fallan la validación la primera vez que se encuentran con una plataforma gubernamental.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card3.note', 'es', 'Esta es sistemáticamente la mayor fuente de rechazos tempranos — merece la pena dedicar una limpieza de datos específica antes de la puesta en marcha, no después.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card4.title', 'es', 'Certificados digitales y firma');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card4.body', 'es', 'Muchos regímenes exigen un certificado digital cualificado para firmar facturas o autenticar llamadas a la API. Los certificados caducan, necesitan procesos de renovación, y a veces hay que delegarlos en un proveedor externo — una tarea administrativa genuinamente continua, no un paso de configuración único.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card5.title', 'es', 'Resiliencia y contingencia');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card5.body', 'es', '¿Qué ocurre cuando la plataforma gubernamental está caída? Varios regímenes definen modos explícitos de contingencia/sin conexión (Offline24 de Polonia, el modo de fallo de Arabia Saudita) — prepararse para esto desde el primer día evita las prisas la primera vez que ocurre de verdad.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card6.title', 'es', 'Obligaciones de archivo');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec2.card6.body', 'es', 'Los períodos de conservación de las facturas electrónicas suelen ser más largos, y más específicos por formato, que las normas contables generales (10 años es habitual; algunas categorías duran más). El archivo estructurado original — no una representación impresa o en PDF — es normalmente lo que debe conservarse.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.heading', 'es', 'Residencia y soberanía de los datos');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.intro', 'es', 'Fácil de pasar por alto si la facturación está centralizada en un centro de servicios compartidos — un mandato en un país puede tener implicaciones sobre dónde y cómo se permite procesar esos datos.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.card1.title', 'es', '¿Dónde residen realmente los datos?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.card1.body', 'es', 'Algunos modelos de compensación dirigen el contenido de las facturas a través de infraestructura gubernamental o intermediarios acreditados localmente por diseño — merece la pena comprobar si su proveedor elegido procesa y almacena los datos dentro del país en cuestión, o en otro lugar.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.card2.title', 'es', 'Conflictos con centros de servicios compartidos');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.card2.body', 'es', 'Una arquitectura habitual — facturación de muchos países procesada centralmente desde un único centro — puede chocar con la expectativa de un país concreto de que ciertos datos permanezcan locales. Merece la pena comprobarlo explícitamente, mercado por mercado, en lugar de asumir que una plataforma global es automáticamente válida en todas partes.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.card3.title', 'es', 'Mayor visibilidad gubernamental');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.card3.body', 'es', 'Los modelos de compensación y reporte en tiempo real dan a las autoridades fiscales una visibilidad mucho más granular y casi en vivo de las transacciones comerciales de lo que nunca dio la presentación periódica. Algunas empresas plantean esto como una preocupación genuina de sensibilidad competitiva que vale la pena señalar a la dirección, aunque no cambie la obligación de cumplimiento en sí.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.card4.title', 'es', 'Riesgo de dependencia del proveedor');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec3.card4.body', 'es', 'Los intermediarios específicos de cada país (un PAC, OSE o Punto de Acceso concreto) pueden convertirse silenciosamente en infraestructura crítica. Entienda su vía de salida/migración antes de depender de uno — algunos regímenes incluso exigen a los proveedores un período mínimo de continuidad precisamente por este motivo.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.heading', 'es', 'Cambios en los procesos y flujos documentales');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.intro', 'es', 'La parte que más sorprende a los equipos financieros: los flujos de trabajo documentales habituales — notas de crédito, notas de débito, correcciones — no siempre sobreviven intactos a un mandato.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.h1', 'es', 'Proceso anterior');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.h2', 'es', 'Qué cambia bajo muchos mandatos');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r1k', 'es', 'Emitir una nota de crédito/débito libremente para corregir un error');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r1v', 'es', 'En su lugar, un proceso formal de "factura rectificativa", a menudo con su propio tipo de documento y reglas de validación — algunos regímenes ya no aceptan notas de corrección ad hoc en absoluto (el KSeF de Polonia retiró la tradicional "nota korygująca" en favor de correcciones estructuradas a través de la propia plataforma)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r2k', 'es', 'Editar o anular una factura emitida directamente');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r2v', 'es', 'Una vez compensada/reportada, muchas facturas no pueden editarse legalmente — la única vía es una nota de crédito formal o un nuevo documento rectificativo, incluso para errores menores');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r3k', 'es', 'Facturar por lotes a fin de mes');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r3v', 'es', 'Las ventanas de emisión ahora se miden en horas o días (24 horas en Arabia Saudita para el reporte B2C; 5 días hábiles en Rumanía y Eslovaquia) obligan a una emisión casi en tiempo real');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r4k', 'es', 'Asumir que una factura es válida una vez enviada');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r4v', 'es', 'Una factura rechazada en un modelo de compensación no tiene ningún efecto legal — en la práctica esto puede retener el envío de mercancías hasta que se resuelva, un problema de cadena de suministro, no solo contable');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r5k', 'es', 'El comprador acepta una factura implícitamente');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec4.table.r5v', 'es', 'Algunos regímenes dan a los compradores una ventana activa de aceptación/rechazo (Malasia: 72 horas) — el silencio no equivale automáticamente a aceptación, y perder esa ventana puede obligar a una nota de crédito/débito completa en lugar de una simple anulación');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.heading', 'es', 'Impacto financiero y comercial');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.intro', 'es', 'Más allá del coste directo del software de cumplimiento, hay efectos de segundo orden que merece la pena plantear pronto a la dirección financiera.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.card1.title', 'es', 'Estructura de costes de cumplimiento');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.card1.body', 'es', 'Las tarifas por transacción de los intermediarios, las licencias de software, los costes de certificados y el trabajo de integración escalan de forma distinta — un modelo de costes que parece razonable a volumen piloto puede verse muy diferente a volumen de producción completo. Modélelo a escala antes de comprometerse con un proveedor.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.card2.title', 'es', 'Flujo de caja, en ambos sentidos');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.card2.body', 'es', 'Algunos regímenes premian la facturación electrónica conforme con plazos de pago más rápidos (objetivos de pago a 5 días en Nueva Zelanda y en el sector público australiano). Pero una compensación rechazada o retrasada puede igualmente retener el pago — el mismo mecanismo corta en ambas direcciones.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.card3.title', 'es', 'La exposición de su cliente, no solo la suya');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.card3.body', 'es', 'En muchos regímenes, una factura no conforme emitida por usted puede bloquear la propia deducción del IVA soportado o la reclamación de gastos de su cliente. Esto convierte su brecha de cumplimiento en el problema financiero de otro — un riesgo real para la relación, no solo interno.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.card4.title', 'es', 'Fricción de entrada al mercado');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec5.card4.body', 'es', 'Entrar en un nuevo mercado con mandato ya no es solo una decisión comercial — puede necesitar un registro local, una relación con un intermediario y la integración técnica en marcha antes de poder facturar legalmente a un solo cliente allí.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.heading', 'es', 'Preparación organizativa');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.intro', 'es', 'El área de impacto más difícil de precisar, y a menudo la que determina si el despliegue técnico realmente transcurre sin problemas.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.card1.title', 'es', 'Un programa, no cinco proyectos');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.card1.body', 'es', 'Que Finanzas, TI, Legal y Ventas/Compras descubran el mandato de forma independiente, cada uno con su propio calendario, es una receta para sorpresas de última hora. Un único responsable multifuncional reduce sustancialmente este riesgo.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.card2.title', 'es', 'Seguimiento del alcance por grupo/filial');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.card2.body', 'es', 'Muchos mandatos se implantan por fases según un umbral de facturación, a veces calculado sobre todo el grupo corporativo en lugar de por entidad (como en las normas de Nueva Zelanda y Malasia). Legal y Finanzas necesitan una visión compartida y actualizada de la estructura del grupo para saber quién está realmente dentro del alcance, y cuándo.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.card3.title', 'es', 'Formación de primera línea');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.card3.body', 'es', 'El personal de entrada de pedidos de ventas y de cuentas por pagar/cobrar es normalmente quien realmente captura los datos maestros más estrictos que exigen estos sistemas — formarlos sobre por qué un identificador fiscal o un código de clasificación importa ahora más que antes se amortiza rápidamente.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.card4.title', 'es', 'Gobernanza continua de los datos');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec6.card4.body', 'es', 'Una limpieza de datos puntual antes de la puesta en marcha se degrada con el tiempo a medida que se añaden nuevos clientes y proveedores. Un proceso permanente de validación de los datos maestros de socios comerciales mantiene bajas las tasas de rechazo de forma permanente, no solo el primer día.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.heading', 'es', 'Preguntas que vale la pena hacerse el primer día');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.intro', 'es', 'Una lista de comprobación rápida y preliminar para cuando un nuevo mandato aparece en su radar — antes de sumergirse en las especificaciones técnicas.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.q1', 'es', '¿Qué entidades legales nuestras están realmente dentro del alcance, y desde qué fecha — verificado frente a los umbrales de facturación del grupo cuando corresponda, no solo las cifras de nuestra propia entidad?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.q2', 'es', '¿Qué modelo de cumplimiento usa este país — post-auditoría, reporte, compensación, plataforma centralizada o basado en Peppol — y qué implica eso para nuestro enfoque de integración?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.q3', 'es', '¿Puede nuestro ERP actual producir el formato requerido de forma nativa, o necesitamos una capa de proveedor de servicios/middleware?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.q4', 'es', '¿Dónde ocurre actualmente la facturación para este mercado — un centro de servicios compartidos, un equipo local — y esa ubicación plantea alguna cuestión de residencia de datos?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.q5', 'es', '¿Cómo es la calidad actual de nuestros datos maestros de clientes/proveedores en este mercado — lo ha comprobado alguien realmente?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.q6', 'es', '¿Qué ocurre operativamente si se rechaza una factura — a quién se notifica, y con qué rapidez puede resolverse antes de que afecte a un envío o a un pago?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.q7', 'es', '¿Quién es el responsable multifuncional de esto — hay una persona designada, o es discretamente el problema de cinco personas distintas?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec7.q8', 'es', '¿Cuál es el coste realista a volumen de producción completo, no a volumen piloto?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.heading', 'es', 'A dónde ir después');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.card1.title', 'es', '📘 Entienda primero los tipos de mandato');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.card1.body', 'es', 'Si aún no lo ha hecho, "Tipos de mandato" (también en Educación) explica con más profundidad los modelos de cumplimiento mencionados en esta página.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.card2.title', 'es', '🗓️ ¿Listo para empezar a planificar?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.card2.body', 'es', '"Preparación para un mandato" (en Educación) cubre a quién involucrar, cuándo empezar y cómo abordar la selección de proveedores.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.card3.title', 'es', '🌍 Consulte los requisitos de su país concreto');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.card3.body', 'es', 'El menú de análisis por país cubre la especificación técnica exacta, los pasos de registro y las sanciones de cada una de las 28 jurisdicciones seguidas aquí.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.card4.title', 'es', '✅ Encuentre un proveedor acreditado');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'sec8.card4.body', 'es', '"Proveedores certificados por el gobierno" (en Educación) enlaza directamente con los registros oficiales del gobierno para proveedores de servicios acreditados, país por país.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-impact-of-mandate', 'footer.text', 'es', 'Esta página ofrece contexto educativo general para ayudar a dimensionar la planificación interna y no constituye asesoramiento legal, fiscal ni de implementación técnica. Los requisitos específicos varían según el país y sus propios sistemas y estructura de grupo — consulte el análisis del país correspondiente y a un asesor cualificado antes de tomar decisiones de implementación.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', '_meta.language', 'es', 'es');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', '_meta.reviewed', 'es', 'true');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'backLink', 'es', '← Volver al panel general');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'header.eyebrow', 'es', 'Educación');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'header.title', 'es', 'Tipos de mandato');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'header.sub', 'es', 'Las normas de facturación electrónica de cada país se reducen a un puñado de modelos subyacentes. Una vez que reconoce cuál usa un país, sus normas específicas dejan de parecer arbitrarias.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'header.lastUpdated', 'es', 'Última actualización:');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'stats.label1', 'es', 'Modelos principales en uso a nivel mundial');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'stats.label2', 'es', 'Variantes de CTC');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'stats.label3', 'es', 'Países mapeados en este seguimiento');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.heading', 'es', 'La única pregunta que lo explica todo');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.intro', 'es', 'Antes de comparar formatos y plazos, ayuda hacerse una sola pregunta sobre el régimen de cualquier país: <strong style="color:var(--text-lo);">¿ve la autoridad fiscal la factura, y si es así, antes o después de que llegue al comprador?</strong>');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card1.title', 'es', 'Nunca (o solo bajo solicitud)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card1.body', 'es', 'La autoridad fiscal no ve las facturas individuales de forma rutinaria — revisa los registros más tarde, durante una auditoría. Este es el modelo menos intervencionista.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card1.note', 'es', 'Ejemplos: Reino Unido, Canadá, Estados Unidos (voluntario).');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card2.title', 'es', 'Después, casi en tiempo real');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card2.body', 'es', 'La factura llega directamente al comprador, pero una copia o resumen de los datos de la transacción se reporta a la autoridad fiscal poco después — a menudo en días, a veces al instante.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card2.note', 'es', 'Ejemplos: la capa de e-reporting de Francia, el SII de España, el RTIR de Hungría.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card3.title', 'es', 'Antes de la entrega — compensación');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card3.body', 'es', 'La factura debe ser validada (y a menudo sellada digitalmente) por la autoridad fiscal, o un intermediario acreditado en su nombre, antes de que pueda llegar legalmente al comprador.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec1.card3.note', 'es', 'Ejemplos: el SDI de Italia, el KSeF de Polonia, el CFDI de México, el ZATCA de Arabia Saudita.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.heading', 'es', 'Los siete modelos en la práctica');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.intro', 'es', 'En la práctica, estas preguntas se combinan en siete arquitecturas reconocibles — la mayoría de los países de este seguimiento encajan claramente en una de ellas.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card1.title', 'es', '1. Post-auditoría');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card1.body', 'es', 'Las empresas intercambian facturas libremente, en el formato que acuerden. La autoridad fiscal revisa los registros después de los hechos, durante una auditoría, en lugar de verificar las transacciones a medida que ocurren.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card2.title', 'es', '2. Reporte en tiempo real (CTC)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card2.body', 'es', 'Las facturas se intercambian directamente entre empresas, pero los datos de la transacción — a veces la factura completa, a veces un resumen — también se reportan a la autoridad fiscal casi en tiempo real, junto con la entrega en lugar de sustituirla.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card3.title', 'es', '3. Compensación (CTC)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card3.body', 'es', 'El modelo más estricto: una factura no tiene efecto legal hasta que la autoridad fiscal (o su delegado) la ha validado y ha devuelto una referencia de compensación. Solo entonces puede entregarse al comprador.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card4.title', 'es', '4. Plataforma centralizada');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card4.body', 'es', 'Un único sistema gestionado por el gobierno maneja tanto la validación como la entrega — comprador y vendedor interactúan con la misma plataforma central en lugar de utilizar el proveedor de su elección.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card5.title', 'es', '5. Intercambio descentralizado — red obligatoria (Peppol)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card5.body', 'es', 'No hay plataforma gubernamental, pero la ley prescribe <em>una red específica</em>. Las empresas se conectan una vez a un Punto de Acceso acreditado, y las facturas se enrutan de igual a igual usando un formato común — el modelo de "4 esquinas" — porque el propio mandato designa a Peppol como el canal requerido.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card6.title', 'es', '6. Mandato de formato únicamente — sin canal prescrito');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card6.body', 'es', 'Un patrón genuinamente más ligero, fácil de confundir con el modelo 5 pero significativamente distinto: la ley exige un formato estructurado, pero no prescribe <em>cómo</em> debe entregarse la factura — correo electrónico, cualquier red, cualquier acuerdo bilateral es válido, siempre que el contenido esté correctamente estructurado. Sin compensación, sin capa de reporte obligatoria, sin red requerida.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card6.note', 'es', 'Dinamarca es una variante aún más ligera — su ley exige la <em>capacidad</em> de enviar/recibir facturas estructuradas, no que cada factura se intercambie realmente de esa forma.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card7.title', 'es', '7. Intercambio descentralizado + reporte (5 esquinas)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec2.card7.body', 'es', 'La red de 4 esquinas de Peppol con un quinto participante añadido: la autoridad fiscal, que recibe los datos de la transacción automáticamente como subproducto del intercambio normal, en lugar de una declaración por separado.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.heading', 'es', 'El "CTC" es una familia, no una sola cosa');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.intro', 'es', 'Los Controles Continuos de Transacciones (CTC) son un término general que abarca los modelos 2 y 3 anteriores — ambos dan a la autoridad fiscal visibilidad casi en tiempo real, pero difieren en un punto que importa enormemente en la práctica: ¿ve el gobierno la factura antes o después de que sea legalmente válida?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.h1', 'es', 'Pregunta');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.h2', 'es', 'CTC — Reporte');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.h3', 'es', 'CTC — Compensación');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r1k', 'es', '¿Quién ve primero la factura?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r1v1', 'es', 'El comprador — el reporte ocurre junto con la entrega o poco después');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r1v2', 'es', 'La autoridad fiscal — nada se entrega hasta que se compensa');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r2k', 'es', 'Validez legal');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r2v1', 'es', 'La factura es válida tal como se emite; el reporte es una obligación paralela');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r2v2', 'es', 'La factura no tiene efecto legal hasta que se compensa');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r3k', 'es', 'Modo de fallo');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r3v1', 'es', 'Un reporte tardío o faltante es un incumplimiento, pero la venta se mantiene');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r3v2', 'es', 'Una factura rechazada bloquea la transacción — las mercancías no pueden enviarse legalmente');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r4k', 'es', 'Latencia típica');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r4v1', 'es', 'Horas a unos días');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r4v2', 'es', 'Segundos a minutos');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r5k', 'es', 'Ejemplo');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r5v1', 'es', 'El e-reporting de Francia para ventas B2C/transfronterizas');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec3.table.r5v2', 'es', 'El SDI de Italia, el KSeF de Polonia');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.heading', 'es', 'Dónde encaja Peppol en todo esto');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.intro', 'es', 'Peppol es fácil de ubicar mal en este panorama — no es un modelo de mandato en sí mismo, es una pieza de infraestructura compartida sobre la que se construyen varios modelos distintos.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.card1.title', 'es', 'Qué es Peppol en realidad');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.card1.body', 'es', 'Una red y formato de mensajería estandarizados (Peppol BIS) que permite a dos empresas conectadas intercambiar facturas estructuradas sin una integración bilateral — se conecta una vez a un Punto de Acceso, no una vez por cada socio comercial.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.card2.title', 'es', 'Pura infraestructura, no una política');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.card2.body', 'es', 'Bélgica y Australia usan ambas Peppol, pero solo una de ellas lo exige por ley hoy. La red es la misma; lo que un gobierno decide añadirle (un mandato, un requisito de reporte, nada en absoluto) es una decisión aparte.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.card3.title', 'es', 'La evolución de 4 esquinas → 5 esquinas');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.card3.body', 'es', 'Añada una quinta esquina — la autoridad fiscal — y la misma red empieza a alimentar automáticamente los datos de transacción al gobierno. Singapur, los EAU y Eslovaquia están construyendo hacia esto.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.flow1', 'es', 'Proveedor');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.flow2', 'es', 'PA del proveedor');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.flow3', 'es', 'PA del comprador');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec4.flow4', 'es', 'Comprador');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.heading', 'es', 'A dónde ir después');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.intro', 'es', 'Esta página es deliberadamente el "mapa" — para el detalle fino de un país concreto, los análisis por país son donde viven los detalles.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.card1.title', 'es', '🌍 Consulte el modelo de un país concreto');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.card1.body', 'es', 'Cada análisis del menú "Deep Dives" indica su modelo de cumplimiento de entrada, en los mismos términos usados en esta página — busque la línea "Compliance model" bajo el nombre del país.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.card2.title', 'es', '🏗️ Vea qué significa esto para su negocio');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.card2.body', 'es', '"Impacto del mandato" (también en Educación) cubre el impacto técnico, de procesos, financiero y organizativo que estos modelos tienen en la práctica.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.card3.title', 'es', '📖 Próximamente más páginas educativas');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.card3.body', 'es', 'Análisis más profundos de los subtipos de CTC, un mapa completo de países conectados a Peppol, y una visión general de los proveedores de servicios en este espacio son adiciones planificadas a este menú.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.card4.title', 'es', '🔔 Reciba una notificación cuando se publiquen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'sec5.card4.body', 'es', 'Los suscriptores obtienen acceso prioritario al nuevo contenido educativo en cuanto se publica, junto con el resumen mensual de cumplimiento.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-mandate-types', 'footer.text', 'es', 'Esta página ofrece contexto educativo general y no constituye asesoramiento legal ni fiscal. Los modelos de cumplimiento pueden evolucionar y de hecho lo hacen — el análisis propio de cada país es la fuente autorizada de sus requisitos específicos actuales.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', '_meta.language', 'es', 'es');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', '_meta.reviewed', 'es', 'true');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'backLink', 'es', '← Volver al panel general');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'header.eyebrow', 'es', 'Educación');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'header.title', 'es', 'Preparación para un mandato');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'header.sub', 'es', 'Una vez que entiende el modelo de mandato y su impacto probable, las preguntas prácticas pasan a ser: ¿quién debe estar en la sala, con cuánta antelación debe empezar esto, y cómo aborda la elección de un proveedor sin arrepentirse un año después?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'header.lastUpdated', 'es', 'Última actualización:');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'stats.label1', 'es', 'Antelación recomendada antes de la puesta en marcha');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'stats.label2', 'es', 'Tamaño típico del grupo de trabajo principal');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'stats.label3', 'es', 'De una selección de proveedor bien ejecutada');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.heading', 'es', 'A quién incluir');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.intro', 'es', 'Una respuesta al mandato sin un único responsable claro, o con las funciones equivocadas ausentes de la sala, es la causa más común de sorpresas de última hora. Aquí tiene un grupo de trabajo que cubre el terreno sin volverse inmanejable.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card1.title', 'es', 'Patrocinador del programa');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card1.body', 'es', 'Un directivo senior de Finanzas o Fiscalidad con autoridad para comprometer presupuesto y resolver desacuerdos entre funciones. Sin esto, el grupo de trabajo puede identificar problemas, pero no siempre actuar sobre ellos con rapidez.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card2.title', 'es', 'Responsable fiscal / de cumplimiento');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card2.body', 'es', 'Es responsable de la interpretación del requisito legal real, hace seguimiento del alcance y los plazos entre entidades, y suele ser quien gestiona la relación con cualquier asesor externo.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card3.title', 'es', 'Responsable de TI/integración');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card3.body', 'es', 'Evalúa lo que los sistemas actuales de ERP/CxP/CxC pueden y no pueden hacer de forma nativa, y gestiona la relación técnica con el proveedor o plataforma que se seleccione.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card4.title', 'es', 'Legal y protección de datos');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card4.body', 'es', 'Revisa los contratos con proveedores, las implicaciones de residencia de datos y las cuestiones de transferencia transfronteriza — incorporado desde el principio, no en la firma del contrato, cuando ya es tarde para influir en la forma del acuerdo.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card5.title', 'es', 'Responsable(s) de negocio/entidad');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card5.body', 'es', 'Alguien responsable de cada país o unidad de negocio afectada — especialmente importante en multinacionales, donde el mismo mandato puede aterrizar de forma distinta según la estructura de la entidad local y los sistemas existentes.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card6.title', 'es', 'Compras / gestión de proveedores');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.card6.body', 'es', 'Dirige el proceso formal de RFP si se necesita uno, y garantiza que los términos del contrato (SLA, cláusulas de salida, responsabilidad) reciben un escrutinio comercial adecuado en lugar de aceptarse como condiciones estándar del proveedor.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec1.outro', 'es', 'Mantenga este grupo entre 6 y 8 personas que se reúnan regularmente, con un círculo más amplio (responsables de equipos de CxP/CxC, clientes o proveedores clave para pruebas, asesores externos) consultado en hitos concretos en lugar de en cada reunión.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.heading', 'es', 'Cuándo empezar');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.intro', 'es', 'Los períodos de gracia y los umbrales escalonados son habituales, y resulta tentador tratarlos como el plazo real. En la práctica, los plazos de entrega de los proveedores, los ciclos de pruebas y la coordinación multifuncional tardan siempre más de lo esperado — empezar pronto es lo que realmente determina si la puesta en marcha es tranquila o caótica.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.marker1', 'es', '12–18 meses antes de la puesta en marcha');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.marker2', 'es', '9–12 meses antes de la puesta en marcha');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.marker3', 'es', '6–9 meses antes de la puesta en marcha');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.marker4', 'es', '3–6 meses antes de la puesta en marcha');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.marker5', 'es', '1–3 meses antes de la puesta en marcha');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.marker6', 'es', 'Puesta en marcha y después');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card1.date', 'es', 'Evaluación y alcance');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card1.badge', 'es', 'Empiece aquí');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card1.title', 'es', 'Confirme el alcance, forme el grupo de trabajo, evalúe los sistemas actuales');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card1.desc', 'es', 'Determine qué entidades están realmente dentro del alcance y desde cuándo, forme el grupo de trabajo principal descrito arriba, y obtenga una valoración honesta de lo que sus sistemas actuales de ERP/CxP/CxC pueden y no pueden hacer sin ayuda.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card2.date', 'es', 'Selección de proveedor y diseño de la solución');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card2.title', 'es', 'Ejecute el proceso de selección de proveedor (véase abajo) y confirme el enfoque técnico');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card2.desc', 'es', 'Esta suele ser la fase individual más larga — trátela como su propio proyecto con su propio calendario, no como un simple trámite de compras.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card3.date', 'es', 'Construcción e integración');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card3.title', 'es', 'Integración técnica, limpieza de datos maestros, diseño de procesos internos');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card3.desc', 'es', 'La limpieza de datos maestros en particular se beneficia de un plazo amplio — rara vez es una solución rápida una vez que se examina realmente el estado de los registros de clientes/proveedores.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card4.date', 'es', 'Pruebas y piloto');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card4.title', 'es', 'Pruebas en entorno de pruebas/certificación, y después un piloto real con un subconjunto reducido de transacciones');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card4.desc', 'es', 'Pruebe deliberadamente las rutas de fallo — rechazos, correcciones, modos de contingencia/sin conexión — no solo el escenario ideal en el que todo se valida a la primera.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card5.date', 'es', 'Ejecución en paralelo y preparación del cutover');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card5.title', 'es', 'Ejecute los procesos antiguos y nuevos en paralelo, forme al personal de primera línea, finalice los planes de contingencia');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card5.desc', 'es', 'Este es también el momento de informar a clientes y proveedores clave sobre los cambios, si el mandato afecta a cómo recibirán o enviarán facturas hacia usted.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card6.date', 'es', 'Estabilización');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card6.title', 'es', 'Monitorice de cerca las tasas de rechazo durante las primeras semanas');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec2.card6.desc', 'es', 'Las tasas de rechazo suelen dispararse inmediatamente después de la puesta en marcha, a medida que surgen casos límite de datos reales que las pruebas no detectaron — dedique atención presupuestaria a esto en lugar de asumir que la puesta en marcha es la línea de meta.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.heading', 'es', 'Planificación de un proceso de selección de proveedor');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.intro', 'es', 'Ya sea que necesite una plataforma de cumplimiento de servicio completo, un intermediario específico de un país (un PAC, OSE o Punto de Acceso), o simplemente un módulo dentro de su ERP actual, el mismo proceso disciplinado da sus frutos.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step1.title', 'es', 'Defina los requisitos antes de hablar con cualquier proveedor');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step1.body', 'es', 'Cobertura de países/formatos necesaria, volumen de transacciones esperado, método de integración requerido (API frente a portal) y rango de presupuesto. Salir al mercado sin esto tiende a producir propuestas difíciles de comparar de forma justa.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step2.title', 'es', 'Mapee el panorama realista de proveedores');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step2.body', 'es', 'Las opciones suelen abarcar plataformas globales de cumplimiento de servicio completo, intermediarios específicos de cada país y módulos nativos añadidos al ERP — cada uno con distintas compensaciones entre amplitud de cobertura, profundidad y coste.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step3.title', 'es', 'Puntúe más allá del precio');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step3.body', 'es', 'Cobertura de formatos/países, SLA de disponibilidad y soporte (incluyendo horarios de soporte respecto a su zona horaria), certificaciones de seguridad, esfuerzo de integración requerido por su parte y — de forma crítica — su historial de mantener el ritmo con los cambios regulatorios en los países que necesita.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step4.title', 'es', 'Insista en una prueba de concepto');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step4.body', 'es', 'Una prueba en entorno de pruebas con sus propios datos reales (o realistas) saca a la luz fricciones de integración que una demostración comercial nunca mostrará. Trátela como innegociable antes de firmar, no como un extra opcional.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step5.title', 'es', 'Examine el contrato, no solo el producto');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step5.body', 'es', 'Compromisos de residencia de datos, responsabilidad por errores o plazos incumplidos, períodos mínimos de continuidad si cambia de proveedor, y condiciones claras de salida/portabilidad de datos — implique a Legal y Compras directamente en esta etapa, no como un mero trámite final.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step6.title', 'es', 'Planifique para el próximo mandato, no solo para este');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec3.step6.body', 'es', 'Si opera en varios mercados, pregunte cómo la hoja de ruta del proveedor cubre países que aún no necesita pero que podría necesitar pronto — cambiar de proveedor de nuevo en dos años es un coste real que vale la pena evitar si una única relación puede crecer razonablemente con usted.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.heading', 'es', 'Errores comunes');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.intro', 'es', 'Patrones que vale la pena vigilar, basados en cómo suelen fallar estos programas.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card1.title', 'es', '⏳ Tratar el período de gracia como el plazo real');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card1.body', 'es', 'Las moratorias de aplicación existen para facilitar la transición, no para señalar que no hay urgencia — el trabajo técnico y de procesos subyacente sigue teniendo que realizarse según el calendario original.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card2.title', 'es', '🗂️ Omitir la limpieza de datos maestros');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card2.body', 'es', 'La causa más común de rechazos tempranos, y lo más fácil de despriorizar bajo presión de tiempo — rara vez compensa omitirla.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card3.title', 'es', '🙋 Ningún responsable único');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card3.body', 'es', 'Cuando Finanzas, TI y Legal piensan cada uno que otro está liderando, las brechas emergen tarde — normalmente justo cuando ya no queda tiempo para solucionarlas.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card4.title', 'es', '🧪 Probar solo el escenario ideal');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card4.body', 'es', 'Los rechazos, las correcciones y los modos de contingencia/sin conexión son precisamente donde aparece el dolor operativo real — pruebe estos deliberadamente, no solo el caso en que todo funciona a la primera.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card5.title', 'es', '🌍 Asumir que la solución de un mercado se traslada al siguiente');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card5.body', 'es', 'Un proveedor o enfoque que funciona bien en el modelo de un país no encaja automáticamente en el de otro — verifique de nuevo el ajuste mercado por mercado en lugar de asumirlo.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card6.title', 'es', '💸 Comparar proveedores con precios de volumen piloto');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec4.card6.body', 'es', 'Las estructuras de costes que parecen similares a bajo volumen pueden divergir considerablemente a volumen de producción real — modele siempre los precios a su escala real esperada.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.heading', 'es', 'Lista de comprobación rápida');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q1', 'es', 'Patrocinador del programa designado con autoridad presupuestaria, confirmado');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q2', 'es', 'Grupo de trabajo principal formado — Fiscalidad, TI, Legal, Compras y unidades de negocio afectadas representadas');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q3', 'es', 'Alcance confirmado: qué entidades, desde cuándo, bajo qué modelo de cumplimiento');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q4', 'es', 'Capacidad del sistema actual evaluada honestamente, brechas documentadas');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q5', 'es', 'Requisitos del proveedor documentados antes de que comiencen las conversaciones con proveedores');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q6', 'es', 'Pruebas de prueba de concepto programadas antes de la firma del contrato, no después');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q7', 'es', 'Plan de limpieza de datos maestros en marcha, no aplazado para "más adelante"');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q8', 'es', 'Flujos de rechazo y corrección probados explícitamente, no asumidos');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec5.q9', 'es', 'Formación de primera línea (CxP/CxC, entrada de pedidos de ventas) programada antes de la puesta en marcha');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.heading', 'es', 'A dónde ir después');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card1.title', 'es', '📘 ¿No está seguro de qué modelo aplica?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card1.body', 'es', '"Tipos de mandato" (en Educación) explica los modelos de cumplimiento mencionados a lo largo de esta página.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card2.title', 'es', '🏗️ Entienda primero el impacto completo');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card2.body', 'es', '"Impacto del mandato" profundiza en los efectos técnicos, de proceso y financieros a los que responde en última instancia este trabajo de planificación.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card3.title', 'es', '🌍 Consulte los requisitos de su país concreto');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card3.body', 'es', 'El menú de análisis por país cubre la especificación técnica exacta, los pasos de registro y las sanciones de cada una de las 28 jurisdicciones seguidas aquí.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card4.title', 'es', '🏷️ Entienda primero el panorama de proveedores');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card4.body', 'es', '"Tipos de proveedor" (en Educación) desglosa las cinco categorías de proveedor mencionadas en el proceso de selección anterior — ERP, Proveedor de Solución, Cumplimiento Fiscal, Tecnología y Consultoría.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card5.title', 'es', '✅ Encuentre un proveedor acreditado');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'sec6.card5.body', 'es', '"Proveedores certificados por el gobierno" (en Educación) enlaza directamente con los registros oficiales mencionados en la sección de selección de proveedor anterior.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-preparing-for-mandate', 'footer.text', 'es', 'Esta página ofrece orientación educativa general basada en patrones comunes de los programas de preparación ante mandatos, y no constituye asesoramiento legal, fiscal ni de compras. Los plazos y requisitos concretos varían según el país y sus propios sistemas y organización — consulte el análisis del país correspondiente y a los asesores adecuados antes de comprometerse con un plan.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', '_meta.language', 'es', 'es');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', '_meta.reviewed', 'es', 'true');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'backLink', 'es', '← Volver al panel general');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'header.eyebrow', 'es', 'Educación');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'header.title', 'es', 'Tipos de proveedor');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'header.sub', 'es', '"Conseguir un proveedor" resta importancia a lo variado que es en realidad este mercado. Cinco categorías genuinamente distintas de proveedor venden soluciones de cumplimiento de facturación electrónica — entender con cuál está hablando cambia lo que debería esperar de él.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'header.lastUpdated', 'es', 'Última actualización:');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'statusBanner.text', 'es', 'Los nombres de empresas a continuación son <strong>únicamente ejemplos ilustrativos</strong> — una muestra pequeña y no exhaustiva para hacer concreta cada categoría, no una recomendación ni una clasificación. Muchos proveedores reales abarcan más de una categoría.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'stats.label1', 'es', 'Categorías de proveedor distintas');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'stats.label2', 'es', 'Categorías que la mayoría de los programas combinan realmente');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'stats.label3', 'es', 'Categoría que lo cubre todo por sí sola');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec1.heading', 'es', 'Por qué la categoría importa antes que el nombre');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec1.intro', 'es', 'Dos proveedores pueden decir ambos "hacemos facturación electrónica" y referirse a cosas genuinamente distintas. Saber qué categoría está evaluando le indica qué preguntas hacer realmente — y qué carencias esperar y planificar.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.heading', 'es', 'Las cinco categorías');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.strengthsLabel', 'es', 'Fortalezas típicas');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.tradeoffsLabel', 'es', 'Compensaciones típicas');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.examplesLabel', 'es', 'Ejemplos ilustrativos:');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card1.title', 'es', '1. Proveedores de ERP');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card1.what', 'es', 'Suites completas de planificación de recursos empresariales — finanzas, cadena de suministro, RR. HH. y más — que han incorporado el cumplimiento de facturación electrónica como módulo nativo o adicional dentro de su propia plataforma.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card1.s1', 'es', 'Nativo en su sistema central de registro — sin una capa de extracción de datos independiente');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card1.s2', 'es', 'Una única relación con proveedor si ya es cliente');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card1.s3', 'es', 'Datos maestros consistentes, ya que nunca salen del ERP');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card1.t1', 'es', 'La cobertura de países y la velocidad de actualización pueden ir por detrás de proveedores especializados, especialmente en mercados más nuevos o pequeños');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card1.t2', 'es', 'A menudo sigue necesitando un módulo adicional o un socio para alcanzar cobertura global completa');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card1.t3', 'es', 'Menos flexible si utiliza más de un ERP en su grupo');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card2.title', 'es', '2. Proveedores de soluciones (especialistas en CxP/CxC)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card2.what', 'es', 'Proveedores centrados específicamente en la automatización de cuentas por pagar y por cobrar, el intercambio de facturas electrónicas, y actuando como el intermediario acreditado (Punto de Acceso, PAC, OSE) que exige el mandato de un país concreto.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card2.s1', 'es', 'Cobertura de países y formatos profunda y a menudo más ágil — es todo su negocio');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card2.s2', 'es', 'Independiente del ERP — diseñado para conectarse con cualquier sistema(s) que ya utilice');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card2.s3', 'es', 'Diseñado específicamente para la capa de intercambio y validación');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card2.t1', 'es', 'Otra relación y contrato con proveedor que gestionar junto a su ERP');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card2.t2', 'es', 'Sigue requiriendo esfuerzo de integración para conectarlo con sus sistemas centrales');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card3.title', 'es', '3. Proveedores de cumplimiento fiscal');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card3.what', 'es', 'Proveedores cuyo negocio principal es el cumplimiento fiscal indirecto más amplio — determinación del IVA/GST, declaraciones y reportes — y que se han extendido a la facturación electrónica como parte de esa pila tecnológica fiscal más amplia.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card3.s1', 'es', 'Un solo proveedor tanto para la determinación fiscal como para la facturación electrónica, si ya lo usa para fiscalidad');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card3.s2', 'es', 'Profunda experiencia técnico-fiscal que sustenta la lógica de cumplimiento');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card3.t1', 'es', 'La facturación electrónica puede ser una parte más nueva de su oferta que su producto fiscal principal — verifique específicamente la madurez de la cobertura por país para esto, no solo su reputación fiscal en general');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card4.title', 'es', '4. Proveedores de tecnología (EDI/middleware)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card4.what', 'es', 'Proveedores cuya competencia principal es el intercambio de datos B2B más amplio y el middleware de integración — a menudo consolidados desde hace tiempo en EDI — que han añadido soporte para formatos de factura electrónica estructurados como extensión de esa capacidad ya existente.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card4.s1', 'es', 'Si ya gestiona un volumen significativo de socios comerciales EDI, extiende la misma capa de integración en lugar de añadir un sistema paralelo');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card4.s2', 'es', 'Sólida capacidad de mapeo y transformación de datos de propósito general');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card4.t1', 'es', 'Los matices específicos de CTC — compensación en tiempo real, firmas digitales, reporte gubernamental — suelen ser una capa más nueva sobre una arquitectura originalmente basada en EDI, no parte de su ADN central');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card5.title', 'es', '5. Consultoras');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card5.what', 'es', 'Firmas de asesoría e implementación — no un producto de software en sí mismas — que ofrecen evaluación, apoyo en la selección de proveedores y gestión de programa para una respuesta al mandato.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card5.s1', 'es', 'Independientes de cualquier proveedor de software concreto, lo que puede significar un apoyo más objetivo en la selección de proveedores');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card5.s2', 'es', 'Útiles para programas complejos, multinacionales y multi-entidad que necesitan gestión de programa dedicada');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card5.t1', 'es', 'No sustituyen la necesidad de un proveedor real de software/servicios — es una capa complementaria');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec2.card5.t2', 'es', 'Normalmente coste por tiempo y materiales en lugar de una tarifa predecible por transacción');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.heading', 'es', 'Comparativa');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.intro', 'es', 'Una guía aproximada de cómo suelen diferir las categorías — los proveedores reales varían, y varios abarcan deliberadamente más de una fila.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.h1', 'es', 'Categoría');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.h2', 'es', 'Negocio principal');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.h3', 'es', 'Profundidad de cobertura por país');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.h4', 'es', 'Modelo de coste típico');
