INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r1c2', 'es', 'Sistema empresarial completo, facturación electrónica como módulo');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r1c3', 'es', 'Variable — fuerte en mercados de origen, puede rezagarse en otros');
