INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r2c2', 'es', 'Automatización de CxP/CxC e intercambio de facturas electrónicas');
INSERT INTO translations (namespace, key, lang, value) VALUES ('edu-types-of-provider', 'sec3.table.r2c3', 'es', 'Normalmente amplia — es su especialidad');
