INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.eyebrow', 'es', 'Nunca más se lleve una sorpresa');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.title', 'es', 'Reciba una notificación en cuanto un gobierno cambie las normas');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.intro', 'es', 'Los umbrales de facturación electrónica, los números de ola y las fechas de puesta en marcha cambian constantemente — a menudo con poco aviso público. Suscríbase una vez y cada actualización o anuncio gubernamental de las 28 jurisdicciones que seguimos llegará automáticamente a su bandeja de entrada, en lenguaje sencillo, antes de que sorprenda a su equipo.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.sampleLink', 'es', '👀 Vea un ejemplar real de muestra (enero de 2026) →');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.stat1', 'es', 'Jurisdicciones seguidas');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.stat2', 'es', 'Cadencia del resumen');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.stat3', 'es', 'Spam entre números');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item1.title', 'es', 'Anuncios gubernamentales reales, resumidos');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item1.body', 'es', 'Cada nuevo mandato, cambio de plazo y actualización de sanciones que seguimos, escrito en lenguaje sencillo — no texto legal copiado y pegado del comunicado de una autoridad fiscal.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item2.title', 'es', 'Elija exactamente los países que le importan');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item2.body', 'es', 'Díganos cuáles de las 28 jurisdicciones importan a su negocio, y su correo de notificación mensual le dirá específicamente si aparecieron — o reciba el resumen global completo si prefiere verlo todo.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item3.title', 'es', 'Un catálogo completo y consultable');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item3.body', 'es', 'Cada número anterior vive en un archivo consultable y filtrable — vuelva a consultar cualquier mes, cualquier país, en cualquier momento, no solo lo último que llegó a su bandeja de entrada.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item4.title', 'es', 'Acceso prioritario a nuevo contenido educativo');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item4.body', 'es', 'Los nuevos análisis por país y guías educativas se señalan primero a los suscriptores, a medida que los publicamos.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.eyebrow', 'es', 'Suscríbase');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.title', 'es', 'Empecemos');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.sub', 'es', 'Un correo al mes, más una breve alerta cada vez que se publique un nuevo número que cubra sus países. Elegirá pago recurrente o único en el siguiente paso, seguro.');
