INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.form.companyError', 'es', 'El nombre de la empresa es obligatorio');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.countriesLabel', 'es', '¿Sobre qué países desea recibir alertas?');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.countriesHint', 'es', 'Opcional — deje todo sin marcar y le enviaremos el resumen mensual completo de las 28 jurisdicciones.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.countriesMissing', 'es', 'La selección de países no está disponible temporalmente — de todas formas recibirá el resumen mensual completo. (Falta el archivo: countries.js)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.selectAll', 'es', 'Seleccionar todo');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.clearAll', 'es', 'Borrar todo');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.submitButton', 'es', 'Continuar al pago seguro');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.fineprint', 'es', 'El pago lo gestiona Lemon Squeezy, nuestro comerciante registrado — ellos recaudan y remiten cualquier IVA/GST aplicable a esta venta, por lo que nunca se le cobra el impuesto por separado. Nunca vemos ni almacenamos los datos de su tarjeta. Consulte nuestra <a href="privacy-policy.html" style="color:#b5432f; text-decoration:underline;">política de privacidad</a> para saber cómo se gestionan sus datos.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'confirm.eyebrow', 'es', 'Un paso más');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'confirm.title', 'es', 'Confirme sus datos');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'confirm.subscribingAs', 'es', 'Suscribiéndose como');
