INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', '_meta.reviewedNote', 'es', 'Traducción generada con asistencia de IA, aprobada para publicación (contenido de navegación, no datos de cumplimiento).');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'brand.eyebrow', 'es', 'Panel de cumplimiento normativo');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'brand.title', 'es', 'The E-Invoicing<br>Compliance Corner');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'brand.description', 'es', 'Un seguimiento actualizado de los mandatos de facturación electrónica y reporte digital en 28 países — normas de ViDA a nivel de la UE, sistemas nacionales de CTC, y todo lo demás. Cada entrada muestra la fecha límite, lo que debe hacer al respecto, y un enlace directo al portal oficial del gobierno, para que pueda pasar de "¿esto nos afecta?" a "esto es lo que hay que hacer" en una sola página.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'perks.heading', 'es', 'Los suscriptores también reciben');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'perks.item1', 'es', 'Un resumen mensual por correo electrónico — cada nuevo mandato o cambio de fecha límite, resumido');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'perks.item2', 'es', 'Acceso completo al archivo del boletín, no solo al número de este mes');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'perks.item3', 'es', 'Acceso prioritario a los nuevos análisis por país en cuanto se publican');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'perks.item4', 'es', 'Resúmenes en lenguaje sencillo sobre "qué significa esto para su equipo", no solo texto legal');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'perks.cta', 'es', 'Suscribirse (Próximamente) →');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.label', 'es', 'Cómo navegar por este sitio');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip1Title', 'es', 'Filtre lo que le interesa');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip1Desc', 'es', 'Use los filtros de región y estado, o el cuadro de búsqueda, para acotar la línea de tiempo a sus mercados.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip2Title', 'es', 'Profundice en un país');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip2Desc', 'es', 'El menú "Deep Dives" enlaza a un análisis técnico completo — formatos de archivo, protocolos de transmisión, pasos de registro y sanciones.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip3Title', 'es', 'Vaya directo a un portal');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip3Desc', 'es', 'La barra lateral (☰ en móvil) enlaza directamente al portal oficial del gobierno de cada país que seguimos aquí.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip4Title', 'es', 'Lo antiguo queda guardado aparte');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip4Desc', 'es', 'La línea de tiempo muestra los cambios recientes y próximos de forma predeterminada — las normativas ya asentadas desde hace tiempo están en la sección plegada de abajo.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'menu.deepDives', 'es', 'Análisis por país');
