INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'about.title', 'es', 'The E-Invoicing Compliance Corner');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'about.p1', 'es', 'The E-Invoicing Compliance Corner se creó en respuesta a la creciente complejidad y rápida expansión de los mandatos de facturación electrónica en todo el mundo. Ya sea una pequeña empresa o una multinacional, este puede ser un tema difícil y costoso de gestionar.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'about.p2', 'es', 'Este sitio tiene como objetivo ofrecer una forma sencilla y de bajo costo de acceder a información precisa con rapidez — y darle alertas continuas cada vez que cambian los mandatos o se introduce nueva legislación.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'languageSwitcher.label', 'es', 'Idioma');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'languageSwitcher.unreviewedBanner', 'es', 'Esta traducción se generó con asistencia de inteligencia artificial y aún no ha sido revisada por un traductor humano. El texto puede ser impreciso — consulte la versión en inglés si algo no queda claro.');
