INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'filters.noResults', 'es', 'Ningún hito coincide con estos filtros.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'filters.footerNote', 'es', 'Datos recopilados de fuentes oficiales de autoridades fiscales y de la Comisión Europea. Los "días restantes" y los indicadores de estado se calculan automáticamente a partir de la fecha de hoy. <a href="privacy-policy.html" style="color:var(--soon);">Política de privacidad</a>');
