INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'filters.establishedRegulations', 'es', 'Normativas ya establecidas');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'filters.daySingular', 'es', 'día');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'filters.dayPlural', 'es', 'días');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'filters.noUpcoming', 'es', 'No hay hitos próximos en el conjunto de datos seguido.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'filters.disclaimer', 'es', 'Este seguimiento refleja la información pública disponible a julio de 2026 y se ofrece con fines meramente informativos, no como asesoramiento legal o fiscal. Los umbrales, números de ola y fechas de entrada en vigor de la facturación electrónica cambian con frecuencia — confirme sus obligaciones directamente en el portal oficial del gobierno enlazado en cada entrada, o con su asesor fiscal, antes de tomar decisiones de cumplimiento.');
