INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'filters.governmentPortals', 'es', 'Portales gubernamentales');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'filters.regionLabel', 'es', 'Región');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'filters.statusLabel', 'es', 'Estado');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'filters.recentAndUpcoming', 'es', 'Recientes y próximos');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'filters.recentIntro', 'es', 'Hitos desde los últimos meses hasta la fecha límite confirmada más lejana. Las normativas ya asentadas se encuentran en la sección plegada de abajo, para que esta lista se centre en lo que realmente está cambiando.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'filters.estLabel', 'es', '— ya en vigor desde hace tiempo, con pocos cambios');
