INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.eyebrow', 'fr', 'Ne soyez plus jamais pris au dépourvu');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.title', 'fr', 'Soyez averti dès qu''un gouvernement change les règles');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.intro', 'fr', 'Les seuils de facturation électronique, les numéros de vague et les dates de mise en service changent constamment — souvent avec peu de préavis public. Abonnez-vous une fois, et chaque mise à jour ou annonce gouvernementale des 28 juridictions que nous suivons arrive automatiquement dans votre boîte de réception, en langage clair, avant qu''elle ne prenne votre équipe au dépourvu.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.sampleLink', 'fr', '👀 Voir un véritable numéro d''exemple (janvier 2026) →');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.stat1', 'fr', 'Juridictions suivies');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.stat2', 'fr', 'Cadence de la synthèse');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.stat3', 'fr', 'Spam entre les numéros');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item1.title', 'fr', 'De véritables annonces gouvernementales, synthétisées');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item1.body', 'fr', 'Chaque nouvelle obligation, échéance modifiée et changement de sanction que nous suivons, rédigé en langage clair — pas un texte juridique copié-collé d''un communiqué de presse d''une administration fiscale.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item2.title', 'fr', 'Choisissez exactement les pays qui vous concernent');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item2.body', 'fr', 'Indiquez-nous lesquelles des 28 juridictions concernent votre entreprise, et votre e-mail de notification mensuel vous dira précisément si elles ont été concernées — ou recevez la synthèse mondiale complète si vous préférez tout voir.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item3.title', 'fr', 'Une archive complète et consultable');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item3.body', 'fr', 'Chaque numéro passé se trouve dans une archive consultable et filtrable — consultez n''importe quel mois, n''importe quel pays, à tout moment, pas seulement ce qui est arrivé le plus récemment dans votre boîte de réception.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item4.title', 'fr', 'Accès prioritaire aux nouveaux contenus pédagogiques');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'benefits.item4.body', 'fr', 'Les nouvelles analyses par pays et guides pédagogiques sont signalés en priorité aux abonnés, dès leur publication.');
