INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.sub', 'fr', 'Un e-mail par mois, plus une courte alerte chaque fois qu''un nouveau numéro concernant vos pays est publié. Vous choisirez paiement récurrent ou unique à l''étape suivante, sécurisée.');
