INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.countriesHint', 'fr', 'Facultatif — laissez tout décoché et nous vous enverrons la synthèse mensuelle complète couvrant les 28 juridictions.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.countriesMissing', 'fr', 'La sélection de pays est temporairement indisponible — vous recevrez tout de même la synthèse mensuelle complète. (Fichier manquant : countries.js)');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.selectAll', 'fr', 'Tout sélectionner');
