INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.submitButton', 'fr', 'Continuer vers le paiement sécurisé');
INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'card.fineprint', 'fr', 'Le paiement est géré par Lemon Squeezy, notre marchand officiel — ils collectent et reversent toute TVA/TPS applicable à cette vente, de sorte que la taxe ne vous est jamais facturée séparément. Nous ne voyons ni ne stockons jamais les détails de votre carte. Consultez notre <a href="privacy-policy.html" style="color:#b5432f; text-decoration:underline;">politique de confidentialité</a> pour savoir comment vos données sont traitées.');
