INSERT INTO translations (namespace, key, lang, value) VALUES ('subscribe', 'confirm.fineprint', 'fr', 'Vous serez redirigé vers une fenêtre de paiement sécurisée Lemon Squeezy, où vous pourrez choisir un paiement récurrent ou unique et finaliser votre achat.');
