INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'brand.eyebrow', 'fr', 'Tableau de suivi de conformité');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'brand.title', 'fr', 'The E-Invoicing<br>Compliance Corner');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'brand.description', 'fr', 'Un suivi actualisé en continu des obligations de facturation électronique et de télédéclaration dans 28 pays — règles ViDA à l''échelle de l''UE, systèmes nationaux de CTC, et tout ce qui se trouve entre les deux. Chaque entrée indique l''échéance, ce qu''il faut faire, et un lien direct vers le portail officiel du gouvernement, pour passer de "est-ce que cela nous concerne ?" à "voici ce qu''il faut faire" en une seule page.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'perks.heading', 'fr', 'Les abonnés bénéficient également de');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'perks.item1', 'fr', 'Une synthèse mensuelle par e-mail — chaque nouvelle obligation ou changement d''échéance, résumé');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'perks.item2', 'fr', 'L''accès complet aux archives de la newsletter, pas seulement au numéro du mois');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'perks.item3', 'fr', 'Un accès prioritaire aux nouvelles analyses par pays dès leur publication');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'perks.item4', 'fr', 'Des synthèses en langage clair sur "ce que cela signifie pour votre équipe", pas seulement du texte juridique');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'perks.cta', 'fr', 'S''abonner (Bientôt disponible) →');
