INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip1Desc', 'fr', 'Utilisez les filtres de région et de statut, ou la barre de recherche, pour cibler la chronologie sur vos marchés.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip2Title', 'fr', 'Approfondissez un pays');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip2Desc', 'fr', 'Le menu "Deep Dives" renvoie vers une analyse technique complète — formats de fichier, protocoles de transmission, étapes d''inscription et sanctions.');
