INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'navTips.tip4Desc', 'fr', 'La chronologie affiche par défaut les changements récents et à venir — les réglementations bien établies depuis longtemps se trouvent dans la section repliée ci-dessous.');
