INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'about.eyebrow', 'fr', 'À propos');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'about.title', 'fr', 'The E-Invoicing Compliance Corner');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'about.p1', 'fr', 'The E-Invoicing Compliance Corner a été créé en réponse à la complexité croissante et à la diffusion rapide des obligations de facturation électronique dans le monde. Qu''il s''agisse d''une petite entreprise ou d''un grand groupe international, ce sujet peut être difficile et coûteux à maîtriser.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'about.p2', 'fr', 'Ce site vise à offrir un accès simple et peu coûteux à une information fiable et rapide — ainsi que des alertes continues à chaque évolution des obligations ou nouvelle législation.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'languageSwitcher.label', 'fr', 'Langue');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'languageSwitcher.unreviewedBanner', 'fr', 'Cette traduction a été générée avec l''assistance de l''IA et n''a pas encore été relue par un traducteur humain. Certaines formulations peuvent être imprécises — consultez la version anglaise en cas de doute.');
