INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'filters.footerNote', 'fr', 'Données compilées à partir de sources officielles des administrations fiscales et de la Commission européenne. Les "jours restants" et les badges de statut sont calculés automatiquement à partir de la date du jour. <a href="privacy-policy.html" style="color:var(--soon);">Politique de confidentialité</a>');
