INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'filters.noUpcoming', 'fr', 'Aucun jalon à venir dans les données suivies.');
INSERT INTO translations (namespace, key, lang, value) VALUES ('tracker', 'filters.disclaimer', 'fr', 'Ce suivi reflète les informations publiques disponibles à juillet 2026 et est fourni à titre informatif général, sans constituer un conseil juridique ou fiscal. Les seuils, numéros de vague et dates de mise en service de la facturation électronique changent fréquemment — vérifiez vos obligations directement sur le portail officiel du gouvernement lié à chaque entrée, ou auprès de votre conseiller fiscal, avant de prendre des décisions de conformité.');
